        INSERT INTO learn_questions (id, question_text, options_json, correct_answer, question_type, subject, chapter, marks, model_answer, marking_scheme_json, case_passage, explanation, difficulty, is_verified)
        VALUES
        ('12041111-0000-4000-8000-000000000001', 'Let A = {1, 2, 3}. Total number of equivalence relations on A containing (1, 2) is:', '{"A":"1","B":"2","C":"3","D":"4"}'::jsonb, 'B', 'MCQ', 'Mathematics', 'Relations and Functions', 1, '{(1,1),(2,2),(3,3),(1,2),(2,1)} and full A×A -> 2 equivalence relations.', NULL, NULL, '{(1,1),(2,2),(3,3),(1,2),(2,1)} and full A×A -> 2 equivalence relations.', 'EASY', true),
        ('12041111-0000-4000-8000-000000000002', 'A function f: R -> R defined by f(x) = x² is:', '{"A":"Injective only","B":"Surjective only","C":"Bijective","D":"Neither one-one nor onto"}'::jsonb, 'D', 'MCQ', 'Mathematics', 'Relations and Functions', 1, 'f(-1) = f(1) = 1 (many-one) and negative reals have no pre-image (not onto).', NULL, NULL, 'f(-1) = f(1) = 1 (many-one) and negative reals have no pre-image (not onto).', 'EASY', true),
        ('12041111-0000-4000-8000-000000000003', 'Number of bijective (one-one onto) functions from a 4-element set A to itself is:', '{"A":"16","B":"24 (4!)","C":"12","D":"8"}'::jsonb, 'B', 'MCQ', 'Mathematics', 'Relations and Functions', 1, '4! = 24 permutations.', NULL, NULL, '4! = 24 permutations.', 'EASY', true),
        ('12041111-0000-4000-8000-000000000004', 'Relation R = {(a, b) : a ≤ b²} on real numbers R is:', '{"A":"Equivalence","B":"Reflexive only","C":"Neither reflexive, nor symmetric, nor transitive","D":"Transitive only"}'::jsonb, 'C', 'MCQ', 'Mathematics', 'Relations and Functions', 1, '(1/2, 1/2) fails reflexivity; (1, 2) holds but (2, 1) fails symmetry; (2, -2) & (-2, 1) fail transitivity.', NULL, NULL, '(1/2, 1/2) fails reflexivity; (1, 2) holds but (2, 1) fails symmetry; (2, -2) & (-2, 1) fail transitivity.', 'EASY', true),
        ('12041111-0000-4000-8000-000000000005', 'If n(A) = 3 and n(B) = 4, total number of one-one functions from A to B is:', '{"A":"64","B":"24 (⁴P_3)","C":"12","D":"81"}'::jsonb, 'B', 'MCQ', 'Mathematics', 'Relations and Functions', 1, '⁴P_3 = 4×3×2 = 24.', NULL, NULL, '⁴P_3 = 4×3×2 = 24.', 'EASY', true),
        ('12041111-0000-4000-8000-000000000006', 'Assertion (A): Every identity relation I_A on a non-empty set A is reflexive, symmetric, and transitive.
