-- V480: Seed 130 Class 12 Mathematics Mock Tests (104 Real-Format 80M Papers + 26 Chapter-Wise 25M Mocks)

DO $$
DECLARE
    v_class_id UUID;
BEGIN
    SELECT id INTO v_class_id FROM learn_exam_types WHERE slug IN ('class-12', 'cbse-class-12') LIMIT 1;
    IF v_class_id IS NULL THEN
        SELECT id INTO v_class_id FROM learn_exam_types WHERE name ILIKE '%Class 12%' LIMIT 1;
    END IF;

    IF v_class_id IS NOT NULL THEN
        DELETE FROM learn_test_questions WHERE mock_test_id IN (SELECT id FROM learn_mock_tests WHERE id::text LIKE '12040000-%');
        DELETE FROM learn_mock_tests WHERE id::text LIKE '12040000-%';

        ON CONFLICT (id) DO NOTHING;

Reason (R): I_A = {(a, a) : a ∈ A} satisfies (a,a)∈I_A and symmetry/transitivity trivially.
Choose the correct option:
A) Both A and R are true, and R is the correct explanation of A.
B) Both A and R are true, and R is not the correct explanation of A.
C) A is true but R is false.
D) A is false but R is true.', '{"A":"Both A and R are true, and R is the correct explanation of A","B":"Both A and R are true, and R is not the correct explanation of A","C":"A is true but R is false","D":"A is false but R is true"}'::jsonb, 'A', 'ASSERTION_REASON', 'Mathematics', 'Relations and Functions', 1, 'Smallest equivalence relation on A.', NULL, NULL, 'Smallest equivalence relation on A.', 'EASY', true),
        ('12041111-0000-4000-8000-000000000007', 'Check whether R = {(a, b) : a ≤ b³} on R is reflexive or symmetric.', NULL, NULL, 'VSA', 'Mathematics', 'Relations and Functions', 2, 'Fails reflexivity at a=1/2 (1/2 > 1/8). Fails symmetry since (1,2)∈R (1≤8) but (2,1)∉R (2>1).', '1M each', NULL, 'Fails reflexivity at a=1/2 (1/2 > 1/8). Fails symmetry since (1,2)∈R (1≤8) but (2,1)∉R (2>1).', 'MEDIUM', true),
        ('12041111-0000-4000-8000-000000000008', 'Show that f: N -> N given by f(x) = 2x is one-one but not onto.', NULL, NULL, 'VSA', 'Mathematics', 'Relations and Functions', 2, 'f(x₁)=f(x₂) => 2x₁=2x₂ => x₁=x₂ (one-one). Odd numbers like 1, 3 ∈ N have no pre-image -> not onto.', '1M each', NULL, 'f(x₁)=f(x₂) => 2x₁=2x₂ => x₁=x₂ (one-one). Odd numbers like 1, 3 ∈ N have no pre-image -> not onto.', 'MEDIUM', true),
        ('12041111-0000-4000-8000-000000000009', 'Prove that f: R - {3} -> R - {1} defined by f(x) = (x - 2)/(x - 3) is bijective.', NULL, NULL, 'SA', 'Mathematics', 'Relations and Functions', 3, 'Injective: (x₁-2)/(x₁-3) = (x₂-2)/(x₂-3) => x₁=x₂. Surjective: y = (x-2)/(x-3) => x = (3y-2)/(y-1) ∈ R-{3} for every y ≠ 1.', 'One-one (1.5M) + Onto (1.5M)', NULL, 'Injective: (x₁-2)/(x₁-3) = (x₂-2)/(x₂-3) => x₁=x₂. Surjective: y = (x-2)/(x-3) => x = (3y-2)/(y-1) ∈ R-{3} for every y ≠ 1.', 'MEDIUM', true),
        ('12041111-0000-4000-8000-00000000000a', 'Let R = {(a, b) ∈ Z×Z : 2 divides (a - b)}. Prove R is an equivalence relation and find equivalence class [0].', NULL, NULL, 'SA', 'Mathematics', 'Relations and Functions', 3, 'Reflexive (2|0), Symmetric (2|(a-b)=>2|(b-a)), Transitive (sum divisible by 2). [0] = set of all even integers.', 'Equivalence proof (2M) + [0] even Z (1M)', NULL, 'Reflexive (2|0), Symmetric (2|(a-b)=>2|(b-a)), Transitive (sum divisible by 2). [0] = set of all even integers.', 'MEDIUM', true),
        ('12041111-0000-4000-8000-00000000000b', 'Show that relation R on N × N defined by (a, b) R (c, d) <=> ad(b + c) = bc(a + d) is an Equivalence Relation. Also, show that f: [-1, 1] -> R given by f(x) = x/(x + 2) is one-one and find its inverse on its range.', NULL, NULL, 'LA', 'Mathematics', 'Relations and Functions', 5, 'Equivalence: rewrite ad(b+c)=bc(a+d) as (b+c)/(bc) = (a+d)/(ad) => 1/b + 1/c = 1/a + 1/d? Careful: 1/c + 1/b = 1/d + 1/a -> better 1/a - 1/b = 1/c - 1/d => trivially reflexive, symmetric, transitive (3M). f(x₁)=f(x₂) => x₁=x₂; inverse y = x/(x+2) => f⁻¹(y) = 2y/(1 - y) (2M).', 'Equivalence (3M) + One-one & inverse (2M)', NULL, 'Equivalence: rewrite ad(b+c)=bc(a+d) as (b+c)/(bc) = (a+d)/(ad) => 1/b + 1/c = 1/a + 1/d? Careful: 1/c + 1/b = 1/d + 1/a -> better 1/a - 1/b = 1/c - 1/d => trivially reflexive, symmetric, transitive (3M). f(x₁)=f(x₂) => x₁=x₂; inverse y = x/(x+2) => f⁻¹(y) = 2y/(1 - y) (2M).', 'HARD', true),
        ('12041111-0000-4000-8000-00000000000c', '(i) Number of reflexive relations on a set of 3 elements. (ii) Check if f(n) = (n+1)/2 (odd n) and n/2 (even n) on N->N is one-one. (iii) Find equivalence class [1] for R = {(a, b) ∈ {0..12} : |a - b| is multiple of 4}. (iv) Bijectivity test of Signum function.', NULL, NULL, 'CASE', 'Mathematics', 'Relations and Functions', 4, '(i) 2^(n²-n) = 2⁶ = 64. (ii) f(1) = 1 and f(2) = 1 -> NOT one-one (many-one, onto). (iii) {1, 5, 9}. (iv) Neither one-one nor onto over R->R.', '4 × 1M = 4M', 'Computer scientists model database equivalence partitions and hash collisions using reflexive, symmetric, and injective mappings.', '(i) 2^(n²-n) = 2⁶ = 64. (ii) f(1) = 1 and f(2) = 1 -> NOT one-one (many-one, onto). (iii) {1, 5, 9}. (iv) Neither one-one nor onto over R->R.', 'HARD', true),
        ('12041111-0000-4000-8000-00000000000d', 'Principal value branch of cos⁻¹(x) is:', '{"A":"[-π/2, π/2]","B":"[0, π]","C":"(0, π)","D":"(-π/2, π/2)"}'::jsonb, 'B', 'MCQ', 'Mathematics', 'Inverse Trigonometric Functions', 1, 'Range [0, π] for cos⁻¹x.', NULL, NULL, 'Range [0, π] for cos⁻¹x.', 'EASY', true),
        ('12041111-0000-4000-8000-00000000000e', 'Principal value of sin⁻¹(-1/2) is:', '{"A":"π/6","B":"-π/6","C":"5π/6","D":"-π/3"}'::jsonb, 'B', 'MCQ', 'Mathematics', 'Inverse Trigonometric Functions', 1, 'sin(-π/6) = -1/2 ∈ [-π/2, π/2].', NULL, NULL, 'sin(-π/6) = -1/2 ∈ [-π/2, π/2].', 'EASY', true),
        ('12041111-0000-4000-8000-00000000000f', 'Value of cos⁻¹(cos(7π/6)) is:', '{"A":"7π/6","B":"5π/6","C":"π/6","D":"-π/6"}'::jsonb, 'B', 'MCQ', 'Mathematics', 'Inverse Trigonometric Functions', 1, 'cos(7π/6) = cos(2π - 5π/6) = cos(5π/6) ∈ [0, π].', NULL, NULL, 'cos(7π/6) = cos(2π - 5π/6) = cos(5π/6) ∈ [0, π].', 'EASY', true),
        ('12041111-0000-4000-8000-000000000010', 'Domain of sin⁻¹(2x - 1) is:', '{"A":"[-1, 1]","B":"[0, 1]","C":"[-1/2, 1/2]","D":"[0, 2]"}'::jsonb, 'B', 'MCQ', 'Mathematics', 'Inverse Trigonometric Functions', 1, '-1 ≤ 2x - 1 ≤ 1 => 0 ≤ x ≤ 1.', NULL, NULL, '-1 ≤ 2x - 1 ≤ 1 => 0 ≤ x ≤ 1.', 'EASY', true),
        ('12041111-0000-4000-8000-000000000011', 'Value of tan⁻¹(√3) - sec⁻¹(-2) is:', '{"A":"π","B":"-π/3","C":"π/3","D":"2π/3"}'::jsonb, 'B', 'MCQ', 'Mathematics', 'Inverse Trigonometric Functions', 1, 'π/3 - (π - π/3) = π/3 - 2π/3 = -π/3.', NULL, NULL, 'π/3 - (π - π/3) = π/3 - 2π/3 = -π/3.', 'EASY', true),
        ('12041111-0000-4000-8000-000000000012', 'Assertion (A): The principal value of tan⁻¹(tan(3π/4)) is -π/4, not 3π/4.
Reason (R): 3π/4 lies outside the principal range (-π/2, π/2) of tan⁻¹x, and tan(3π/4) = tan(-π/4) = -1.
Choose the correct option:
A) Both A and R are true, and R is the correct explanation of A.
B) Both A and R are true, and R is not the correct explanation of A.
C) A is true but R is false.
D) A is false but R is true.', '{"A":"Both A and R are true, and R is the correct explanation of A","B":"Both A and R are true, and R is not the correct explanation of A","C":"A is true but R is false","D":"A is false but R is true"}'::jsonb, 'A', 'ASSERTION_REASON', 'Mathematics', 'Inverse Trigonometric Functions', 1, 'Principal branch restricts range to (-π/2, π/2).', NULL, NULL, 'Principal branch restricts range to (-π/2, π/2).', 'EASY', true),
        ('12041111-0000-4000-8000-000000000013', 'Evaluate: sin(π/3 - sin⁻¹(-1/2)).', NULL, NULL, 'VSA', 'Mathematics', 'Inverse Trigonometric Functions', 2, 'sin(π/3 - (-π/6)) = sin(π/2) = 1.', '2M', NULL, 'sin(π/3 - (-π/6)) = sin(π/2) = 1.', 'MEDIUM', true),
        ('12041111-0000-4000-8000-000000000014', 'Write cot⁻¹(1 / √(x² - 1)), |x| > 1 in simplest form.', NULL, NULL, 'VSA', 'Mathematics', 'Inverse Trigonometric Functions', 2, 'Put x = sec θ -> cot⁻¹(1/tan θ) = cot⁻¹(cot θ) = θ = sec⁻¹ x (or π/2 - cosec⁻¹ x).', 'Substitution (1M) + sec⁻¹ x (1M)', NULL, 'Put x = sec θ -> cot⁻¹(1/tan θ) = cot⁻¹(cot θ) = θ = sec⁻¹ x (or π/2 - cosec⁻¹ x).', 'MEDIUM', true),
        ('12041111-0000-4000-8000-000000000015', 'Express tan⁻¹(cos x / (1 - sin x)), -3π/2 < x < π/2, in simplest form.', NULL, NULL, 'SA', 'Mathematics', 'Inverse Trigonometric Functions', 3, 'Convert cos x = sin(π/2-x) or cos²(x/2)-sin²(x/2) & 1-sin x = (cos x/2 - sin x/2)² -> tan⁻¹[tan(π/4 + x/2)] = π/4 + x/2.', 'Trig simplification (2M) + π/4 + x/2 (1M)', NULL, 'Convert cos x = sin(π/2-x) or cos²(x/2)-sin²(x/2) & 1-sin x = (cos x/2 - sin x/2)² -> tan⁻¹[tan(π/4 + x/2)] = π/4 + x/2.', 'MEDIUM', true),
        ('12041111-0000-4000-8000-000000000016', 'Prove: tan⁻¹(√(1+x) - √(1-x)) / (√(1+x) + √(1-x)) = π/4 - ½ cos⁻¹ x (for -1/√2 ≤ x ≤ 1).', NULL, NULL, 'SA', 'Mathematics', 'Inverse Trigonometric Functions', 3, 'Put x = cos 2θ => numerator/denominator simplifies to tan(π/4 - θ) -> π/4 - θ = π/4 - ½ cos⁻¹ x.', 'Substitution (1.5M) + Proof (1.5M)', NULL, 'Put x = cos 2θ => numerator/denominator simplifies to tan(π/4 - θ) -> π/4 - θ = π/4 - ½ cos⁻¹ x.', 'MEDIUM', true),
        ('12041111-0000-4000-8000-000000000017', 'Draw/verify domain and principal value ranges for all six inverse trigonometric functions. Simplify sin⁻¹(sin 10) or solve for x: tan⁻¹(2x) + tan⁻¹(3x) = π/4, x > 0. Also prove cos⁻¹(4/5) + cos⁻¹(12/13) = cos⁻¹(33/65).', NULL, NULL, 'LA', 'Mathematics', 'Inverse Trigonometric Functions', 5, 'Solve tan⁻¹((5x)/(1-6x²)) = π/4 => 6x² + 5x - 1 = 0 => (6x-1)(x+1)=0 => x = 1/6 (since x > 0) (2.5M). cos⁻¹(48/65 - 15/65) = cos⁻¹(33/65) (2.5M).', 'Equation x=1/6 (2.5M) + Identity proof (2.5M)', NULL, 'Solve tan⁻¹((5x)/(1-6x²)) = π/4 => 6x² + 5x - 1 = 0 => (6x-1)(x+1)=0 => x = 1/6 (since x > 0) (2.5M). cos⁻¹(48/65 - 15/65) = cos⁻¹(33/65) (2.5M).', 'HARD', true),
        ('12041111-0000-4000-8000-000000000018', '(i) Value of sin⁻¹(1/√2) + cos⁻¹(-1/2). (ii) Principal value of cosec⁻¹(2). (iii) Simplify tan⁻¹((cos x - sin x)/(cos x + sin x)), -π/4 < x < 3π/4. (iv) Domain of cos⁻¹(x² - 4).', NULL, NULL, 'CASE', 'Mathematics', 'Inverse Trigonometric Functions', 4, '(i) π/4 + 2π/3 = 11π/12. (ii) π/6. (iii) π/4 - x. (iv) -1 ≤ x²-4 ≤ 1 => 3 ≤ x² ≤ 5 => [-√5, -√3] ∪ [√3, √5].', '4 × 1M = 4M', 'Robotics inverse-kinematics engines map end-effector Cartesian targets into principal-branch servo joint angles safely within [-π/2, π/2] and [0, π].', '(i) π/4 + 2π/3 = 11π/12. (ii) π/6. (iii) π/4 - x. (iv) -1 ≤ x²-4 ≤ 1 => 3 ≤ x² ≤ 5 => [-√5, -√3] ∪ [√3, √5].', 'HARD', true),
        ('12041111-0000-4000-8000-000000000019', 'If matrix A has order m × n and B has order n × p, then order of AB is:', '{"A":"n × n","B":"m × p","C":"p × m","D":"m × n"}'::jsonb, 'B', 'MCQ', 'Mathematics', 'Matrices', 1, 'Inner dimensions match; outer m × p remains.', NULL, NULL, 'Inner dimensions match; outer m × p remains.', 'EASY', true),
        ('12041111-0000-4000-8000-00000000001a', 'Number of all possible 3 × 3 matrices with each entry 0 or 1 is:', '{"A":"27","B":"512 (2⁹)","C":"81","D":"18"}'::jsonb, 'B', 'MCQ', 'Mathematics', 'Matrices', 1, '9 entries, 2 choices each -> 2⁹ = 512.', NULL, NULL, '9 entries, 2 choices each -> 2⁹ = 512.', 'EASY', true),
        ('12041111-0000-4000-8000-00000000001b', 'For any square matrix A with real entries, A + A'' and A - A'' respectively are:', '{"A":"Skew-symmetric and Symmetric","B":"Symmetric and Skew-symmetric","C":"Both diagonal","D":"Both zero"}'::jsonb, 'B', 'MCQ', 'Mathematics', 'Matrices', 1, '(A+A'')'' = A+A''; (A-A'')'' = -(A-A'').', NULL, NULL, '(A+A'')'' = A+A''; (A-A'')'' = -(A-A'').', 'EASY', true),
        ('12041111-0000-4000-8000-00000000001c', 'Every diagonal element of a skew-symmetric matrix is ALWAYS:', '{"A":"1","B":"-1","C":"0","D":"Any integer"}'::jsonb, 'C', 'MCQ', 'Mathematics', 'Matrices', 1, 'a_ii = -a_ii => 2a_ii = 0 => a_ii = 0.', NULL, NULL, 'a_ii = -a_ii => 2a_ii = 0 => a_ii = 0.', 'EASY', true),
        ('12041111-0000-4000-8000-00000000001d', 'If A is a square matrix such that A² = A, then (I + A)³ - 7A simplifies to:', '{"A":"A","B":"I","C":"3A","D":"I - A"}'::jsonb, 'B', 'MCQ', 'Mathematics', 'Matrices', 1, 'I + 3A + 3A² + A³ - 7A = I + 7A - 7A = I.', NULL, NULL, 'I + 3A + 3A² + A³ - 7A = I + 7A - 7A = I.', 'EASY', true),
        ('12041111-0000-4000-8000-00000000001e', 'Assertion (A): Matrix multiplication in general is NOT commutative (AB ≠ BA).
Reason (R): Even when both AB and BA are defined, their orders or corresponding dot products need not match.
Choose the correct option:
A) Both A and R are true, and R is the correct explanation of A.
B) Both A and R are true, and R is not the correct explanation of A.
C) A is true but R is false.
D) A is false but R is true.', '{"A":"Both A and R are true, and R is the correct explanation of A","B":"Both A and R are true, and R is not the correct explanation of A","C":"A is true but R is false","D":"A is false but R is true"}'::jsonb, 'A', 'ASSERTION_REASON', 'Mathematics', 'Matrices', 1, 'Non-commutativity of matrices.', NULL, NULL, 'Non-commutativity of matrices.', 'EASY', true),
        ('12041111-0000-4000-8000-00000000001f', 'Construct a 2 × 2 matrix A = [a_ij] whose elements are given by a_ij = |i - 2j| / 2.', NULL, NULL, 'VSA', 'Mathematics', 'Matrices', 2, 'a₁₁ = 1/2, a₁₂ = 3/2, a₂₁ = 0, a₂₂ = 1 -> [[1/2, 3/2], [0, 1]].', '2M', NULL, 'a₁₁ = 1/2, a₁₂ = 3/2, a₂₁ = 0, a₂₂ = 1 -> [[1/2, 3/2], [0, 1]].', 'MEDIUM', true),
        ('12041111-0000-4000-8000-000000000020', 'If A = [[cos α, -sin α], [sin α, cos α]] and A + A'' = I, find α (acute).', NULL, NULL, 'VSA', 'Mathematics', 'Matrices', 2, '2 cos α = 1 => cos α = 1/2 => α = π/3.', '1M + 1M', NULL, '2 cos α = 1 => cos α = 1/2 => α = π/3.', 'MEDIUM', true),
        ('12041111-0000-4000-8000-000000000021', 'Express matrix B = [[2, -2, -4], [-1, 3, 4], [1, -2, -3]] as the sum of a symmetric matrix P and a skew-symmetric matrix Q.', NULL, NULL, 'SA', 'Mathematics', 'Matrices', 3, 'P = ½(B + B'') = [[2, -3/2, -3/2], [-3/2, 3, 1], [-3/2, 1, -3]]; Q = ½(B - B'') = [[0, -1/2, -5/2], [1/2, 0, 3], [5/2, -3, 0]]. Verify P + Q = B.', 'P (1.5M) + Q (1.5M)', NULL, 'P = ½(B + B'') = [[2, -3/2, -3/2], [-3/2, 3, 1], [-3/2, 1, -3]]; Q = ½(B - B'') = [[0, -1/2, -5/2], [1/2, 0, 3], [5/2, -3, 0]]. Verify P + Q = B.', 'MEDIUM', true),
        ('12041111-0000-4000-8000-000000000022', 'If A = [[3, 1], [-1, 2]], show that A² - 5A + 7I = O and hence find A⁻¹.', NULL, NULL, 'SA', 'Mathematics', 'Matrices', 3, 'A² = [[8, 5], [-5, 3]] -> 8-15+7=0, etc. Multiply by A⁻¹: A - 5I + 7A⁻¹ = O => A⁻¹ = (1/7)(5I - A) = (1/7)[[2, -1], [1, 3]].', 'Verification (1.5M) + A⁻¹ (1.5M)', NULL, 'A² = [[8, 5], [-5, 3]] -> 8-15+7=0, etc. Multiply by A⁻¹: A - 5I + 7A⁻¹ = O => A⁻¹ = (1/7)(5I - A) = (1/7)[[2, -1], [1, 3]].', 'MEDIUM', true),
        ('12041111-0000-4000-8000-000000000023', 'If F(x) = [[cos x, -sin x, 0], [sin x, cos x, 0], [0, 0, 1]], prove that F(x)·F(y) = F(x + y). Also find matrix X such that X [[1, 2, 3], [4, 5, 6]] = [[-7, -8, -9], [2, 4, 6]].', NULL, NULL, 'LA', 'Mathematics', 'Matrices', 5, 'F(x)F(y) via compound angle cos(x+y)/sin(x+y) formulas (2.5M). X is 2×2 [[a,b],[c,d]]: a+4b=-7, 2a+5b=-8 => a=1, b=-2; c+4d=2, 2c+5d=4 => c=2, d=0 -> X = [[1, -2], [2, 0]] (2.5M).', 'F(x)F(y) proof (2.5M) + Matrix X (2.5M)', NULL, 'F(x)F(y) via compound angle cos(x+y)/sin(x+y) formulas (2.5M). X is 2×2 [[a,b],[c,d]]: a+4b=-7, 2a+5b=-8 => a=1, b=-2; c+4d=2, 2c+5d=4 => c=2, d=0 -> X = [[1, -2], [2, 0]] (2.5M).', 'HARD', true),
        ('12041111-0000-4000-8000-000000000024', '(i) Condition for AB to be symmetric if A and B are symmetric matrices. (ii) Find x, y, z if [[x+y+z], [x+z], [y+z]] = [[9], [5], [7]]. (iii) Order of A'' B if A is 3×2 and B is 3×4. (iv) If A is skew-symmetric and odd order 3×3, value of |A|.', NULL, NULL, 'CASE', 'Mathematics', 'Matrices', 4, '(i) AB = BA (commute). (ii) y = 9-5=4; z = 7-4=3; x = 5-3=2. (iii) A'' is 2×3, B is 3×4 -> 2 × 4. (iv) Zero.', '4 × 1M = 4M', 'Computer graphics engines apply 2D/3D rotation matrices F(θ) and store sparse image transformations as symmetric + skew-symmetric matrix decompositions.', '(i) AB = BA (commute). (ii) y = 9-5=4; z = 7-4=3; x = 5-3=2. (iii) A'' is 2×3, B is 3×4 -> 2 × 4. (iv) Zero.', 'HARD', true),
        ('12041111-0000-4000-8000-000000000025', 'If A is a square matrix of order 3 and |A| = 5, then |3A| equals:', '{"A":"15","B":"45","C":"135","D":"5"}'::jsonb, 'C', 'MCQ', 'Mathematics', 'Determinants', 1, '|kA| = k^n |A| = 3³ × 5 = 135.', NULL, NULL, '|kA| = k^n |A| = 3³ × 5 = 135.', 'EASY', true),
        ('12041111-0000-4000-8000-000000000026', 'For an invertible 3 × 3 matrix A, |adj A| equals:', '{"A":"|A|","B":"|A|²","C":"|A|³","D":"1/|A|"}'::jsonb, 'B', 'MCQ', 'Mathematics', 'Determinants', 1, '|adj A| = |A|^(n-1) = |A|².', NULL, NULL, '|adj A| = |A|^(n-1) = |A|².', 'EASY', true),
        ('12041111-0000-4000-8000-000000000027', 'If A and B are invertible matrices of same order, then (AB)⁻¹ equals:', '{"A":"A⁻¹ B⁻¹","B":"B⁻¹ A⁻¹","C":"AB","D":"|A||B|"}'::jsonb, 'B', 'MCQ', 'Mathematics', 'Determinants', 1, 'Reversal law of inverses.', NULL, NULL, 'Reversal law of inverses.', 'EASY', true),
        ('12041111-0000-4000-8000-000000000028', 'If area of triangle with vertices (2, -6), (5, 4), and (k, 4) is 35 sq units, then k is:', '{"A":"12","B":"-2","C":"12 or -2","D":"0"}'::jsonb, 'C', 'MCQ', 'Mathematics', 'Determinants', 1, '½|50 - 10k| = 35 => |5 - k| = 7 => k = -2 or 12.', NULL, NULL, '½|50 - 10k| = 35 => |5 - k| = 7 => k = -2 or 12.', 'EASY', true),
        ('12041111-0000-4000-8000-000000000029', 'System AX = B is consistent with a unique solution if:', '{"A":"|A| = 0","B":"|A| ≠ 0","C":"adj(A) = O","D":"B = O"}'::jsonb, 'B', 'MCQ', 'Mathematics', 'Determinants', 1, 'Non-singular coefficient matrix guarantees X = A⁻¹B.', NULL, NULL, 'Non-singular coefficient matrix guarantees X = A⁻¹B.', 'EASY', true),
        ('12041111-0000-4000-8000-00000000002a', 'Assertion (A): A square matrix A is singular if and only if |A| = 0.
Reason (R): Since A⁻¹ = adj(A)/|A|, division by zero makes A⁻¹ undefined when |A| = 0.
Choose the correct option:
A) Both A and R are true, and R is the correct explanation of A.
B) Both A and R are true, and R is not the correct explanation of A.
C) A is true but R is false.
D) A is false but R is true.', '{"A":"Both A and R are true, and R is the correct explanation of A","B":"Both A and R are true, and R is not the correct explanation of A","C":"A is true but R is false","D":"A is false but R is true"}'::jsonb, 'A', 'ASSERTION_REASON', 'Mathematics', 'Determinants', 1, '|A| = 0 blocks matrix inversion.', NULL, NULL, '|A| = 0 blocks matrix inversion.', 'EASY', true),
        ('12041111-0000-4000-8000-00000000002b', 'Find equation of line joining (1, 2) and (3, 6) using determinants.', NULL, NULL, 'VSA', 'Mathematics', 'Determinants', 2, '|x y 1; 1 2 1; 3 6 1| = 0 => x(-4) - y(-2) + 0 = 0 => y = 2x.', '2M', NULL, '|x y 1; 1 2 1; 3 6 1| = 0 => x(-4) - y(-2) + 0 = 0 => y = 2x.', 'MEDIUM', true),
        ('12041111-0000-4000-8000-00000000002c', 'If |2x, 5; 8, x| = |6, -2; 7, 3|, find x.', NULL, NULL, 'VSA', 'Mathematics', 'Determinants', 2, '2x² - 40 = 18 - (-14) = 32 => 2x² = 72 => x = ±6.', '2M', NULL, '2x² - 40 = 18 - (-14) = 32 => 2x² = 72 => x = ±6.', 'MEDIUM', true),
        ('12041111-0000-4000-8000-00000000002d', 'Verify A(adj A) = |A| I for matrix A = [[2, 3], [-4, -6]] or invertible A = [[3, 1], [-1, 2]] and find A⁻¹.', NULL, NULL, 'SA', 'Mathematics', 'Determinants', 3, 'For [[3,1],[-1,2]]: |A| = 7, adj A = [[2, -1], [1, 3]], A(adj A) = [[7, 0], [0, 7]] = 7I; A⁻¹ = (1/7)[[2,-1],[1,3]].', 'adj A (1.5M) + Verify & A⁻¹ (1.5M)', NULL, 'For [[3,1],[-1,2]]: |A| = 7, adj A = [[2, -1], [1, 3]], A(adj A) = [[7, 0], [0, 7]] = 7I; A⁻¹ = (1/7)[[2,-1],[1,3]].', 'MEDIUM', true),
        ('12041111-0000-4000-8000-00000000002e', 'Solve using Matrix Method: 5x + 2y = 4 and 7x + 3y = 5.', NULL, NULL, 'SA', 'Mathematics', 'Determinants', 3, '|A| = 15 - 14 = 1; A⁻¹ = [[3, -2], [-7, 5]] -> X = A⁻¹B = [[12 - 10], [-28 + 25]] = [[2], [-3]] => x = 2, y = -3.', 'A⁻¹ (1.5M) + x=2, y=-3 (1.5M)', NULL, '|A| = 15 - 14 = 1; A⁻¹ = [[3, -2], [-7, 5]] -> X = A⁻¹B = [[12 - 10], [-28 + 25]] = [[2], [-3]] => x = 2, y = -3.', 'MEDIUM', true),
        ('12041111-0000-4000-8000-00000000002f', 'Using Matrix Method, solve the system of linear equations:
x - y + 2z = 7
3x + 4y - 5z = -5
2x - y + 3z = 12', NULL, NULL, 'LA', 'Mathematics', 'Determinants', 5, '|A| = 1(12-5) + 1(9+10) + 2(-3-8) = 7 + 19 - 22 = 4 ≠ 0 (1.5M). Cofactor matrix & adj A = [[7, 1, -3], [-19, -1, 11], [-11, -1, 7]] (2M). X = (1/4) adj(A) B = (1/4)[[49-5-36], [-133+5+132], [-77+5+84]] = [[2], [1], [3]] -> x = 2, y = 1, z = 3 (1.5M).', '|A|=4 (1.5M) + adj A (2M) + (2,1,3) (1.5M)', NULL, '|A| = 1(12-5) + 1(9+10) + 2(-3-8) = 7 + 19 - 22 = 4 ≠ 0 (1.5M). Cofactor matrix & adj A = [[7, 1, -3], [-19, -1, 11], [-11, -1, 7]] (2M). X = (1/4) adj(A) B = (1/4)[[49-5-36], [-133+5+132], [-77+5+84]] = [[2], [1], [3]] -> x = 2, y = 1, z = 3 (1.5M).', 'HARD', true),
        ('12041111-0000-4000-8000-000000000030', '(i) If A is 3×3 invertible and |A⁻¹| = 1/4, find |A| and |adj(2A)|. (ii) Given product A = [[1,-1,2],[0,2,-3],[3,-2,4]] and B = [[-2,0,1],[9,2,-3],[6,1,-2]], compute AB = I. (iii) Use result (ii) directly to solve x - y + 2z = 1, 2y - 3z = 1, 3x - 2y + 4z = 2. (iv) Condition for collinearity of three points using determinant.', NULL, NULL, 'CASE', 'Mathematics', 'Determinants', 4, '(i) |A| = 4; |2A| = 8×4 = 32 -> |adj(2A)| = 32² = 1024. (ii) AB = I => A⁻¹ = B. (iii) X = B [[1],[1],[2]] = [[0], [5], [3]] => x=0, y=5, z=3. (iv) Δ = 0.', '4 × 1M = 4M', 'Circuit mesh current analysers solve multi-loop Kirchhoff equations rapidly using pre-inverted conductance matrices A⁻¹.', '(i) |A| = 4; |2A| = 8×4 = 32 -> |adj(2A)| = 32² = 1024. (ii) AB = I => A⁻¹ = B. (iii) X = B [[1],[1],[2]] = [[0], [5], [3]] => x=0, y=5, z=3. (iv) Δ = 0.', 'HARD', true),
        ('12041111-0000-4000-8000-000000000031', 'Value of k for which f(x) = { (kx)/|x| if x<0; 3 if x≥0 } is continuous at x = 0 is:', '{"A":"3","B":"-3","C":"0","D":"1"}'::jsonb, 'B', 'MCQ', 'Mathematics', 'Continuity and Differentiability', 1, 'LHL = k(-1) = -k = 3 => k = -3.', NULL, NULL, 'LHL = k(-1) = -k = 3 => k = -3.', 'EASY', true),
        ('12041111-0000-4000-8000-000000000032', 'Derivative of sin(x²) with respect to x² is:', '{"A":"2x cos(x²)","B":"cos(x²)","C":"sin(x²)","D":"2x"}'::jsonb, 'B', 'MCQ', 'Mathematics', 'Continuity and Differentiability', 1, 'Let u = x² -> d(sin u)/du = cos u = cos(x²).', NULL, NULL, 'Let u = x² -> d(sin u)/du = cos u = cos(x²).', 'EASY', true),
        ('12041111-0000-4000-8000-000000000033', 'If y = e^(x + e^(x + ... ∞)), then dy/dx equals:', '{"A":"y / (1 - y)","B":"y / (1 + y)","C":"1 / (1 - y)","D":"e^x"}'::jsonb, 'A', 'MCQ', 'Mathematics', 'Continuity and Differentiability', 1, 'y = e^(x+y) => ln y = x + y => (1/y - 1)y'' = 1 => y'' = y/(1-y).', NULL, NULL, 'y = e^(x+y) => ln y = x + y => (1/y - 1)y'' = 1 => y'' = y/(1-y).', 'EASY', true),
        ('12041111-0000-4000-8000-000000000034', 'Greatest Integer Function f(x) = [x] is NOT differentiable at:', '{"A":"All real numbers","B":"All integers Z (because discontinuous at integers)","C":"Half-integers","D":"x = 0 only"}'::jsonb, 'B', 'MCQ', 'Mathematics', 'Continuity and Differentiability', 1, 'Discontinuous jump at every integer prevents differentiability.', NULL, NULL, 'Discontinuous jump at every integer prevents differentiability.', 'EASY', true),
        ('12041111-0000-4000-8000-000000000035', 'If x = a cos θ and y = a sin θ, then dy/dx equals:', '{"A":"tan θ","B":"-cot θ","C":"cot θ","D":"-tan θ"}'::jsonb, 'B', 'MCQ', 'Mathematics', 'Continuity and Differentiability', 1, '(a cos θ)/(-a sin θ) = -cot θ.', NULL, NULL, '(a cos θ)/(-a sin θ) = -cot θ.', 'EASY', true),
        ('12041111-0000-4000-8000-000000000036', 'Assertion (A): Every differentiable function at a point is necessarily continuous at that point.
Reason (R): If f''(c) exists finitely, lim_{h->0} [f(c+h) - f(c)] = f''(c)·0 = 0 => lim f(x) = f(c).
Choose the correct option:
A) Both A and R are true, and R is the correct explanation of A.
B) Both A and R are true, and R is not the correct explanation of A.
C) A is true but R is false.
D) A is false but R is true.', '{"A":"Both A and R are true, and R is the correct explanation of A","B":"Both A and R are true, and R is not the correct explanation of A","C":"A is true but R is false","D":"A is false but R is true"}'::jsonb, 'A', 'ASSERTION_REASON', 'Mathematics', 'Continuity and Differentiability', 1, 'Differentiability implies continuity (converse |x| fails at 0).', NULL, NULL, 'Differentiability implies continuity (converse |x| fails at 0).', 'EASY', true),
        ('12041111-0000-4000-8000-000000000037', 'Find dy/dx if y + sin y = cos x.', NULL, NULL, 'VSA', 'Mathematics', 'Continuity and Differentiability', 2, 'dy/dx (1 + cos y) = -sin x => dy/dx = -sin x / (1 + cos y).', 'Implicit diff (2M)', NULL, 'dy/dx (1 + cos y) = -sin x => dy/dx = -sin x / (1 + cos y).', 'MEDIUM', true),
        ('12041111-0000-4000-8000-000000000038', 'Differentiate x^(sin x) + (sin x)^x with respect to x (just x^(sin x) for 2M).', NULL, NULL, 'VSA', 'Mathematics', 'Continuity and Differentiability', 2, 'u = x^(sin x) -> du/dx = x^(sin x)[ (sin x)/x + cos x · ln x ].', 'Logarithmic diff (2M)', NULL, 'u = x^(sin x) -> du/dx = x^(sin x)[ (sin x)/x + cos x · ln x ].', 'MEDIUM', true),
        ('12041111-0000-4000-8000-000000000039', 'If y = (tan⁻¹ x)², show that (x² + 1)² y₂ + 2x(x² + 1) y₁ = 2.', NULL, NULL, 'SA', 'Mathematics', 'Continuity and Differentiability', 3, 'y₁ = 2 tan⁻¹x / (1+x²) => (1+x²)y₁ = 2 tan⁻¹x. Differentiate again -> (1+x²)y₂ + 2x y₁ = 2/(1+x²) -> multiply by (1+x²).', 'y₁ relation (1.5M) + 2nd derivative proof (1.5M)', NULL, 'y₁ = 2 tan⁻¹x / (1+x²) => (1+x²)y₁ = 2 tan⁻¹x. Differentiate again -> (1+x²)y₂ + 2x y₁ = 2/(1+x²) -> multiply by (1+x²).', 'MEDIUM', true),
        ('12041111-0000-4000-8000-00000000003a', 'Find constants a and b so that f(x) = { 5 if x≤2; ax+b if 2<x<10; 21 if x≥10 } is continuous everywhere.', NULL, NULL, 'SA', 'Mathematics', 'Continuity and Differentiability', 3, 'At x=2: 2a + b = 5. At x=10: 10a + b = 21. Subtract: 8a = 16 => a = 2, b = 1.', 'Continuity eqs (1.5M) + a=2, b=1 (1.5M)', NULL, 'At x=2: 2a + b = 5. At x=10: 10a + b = 21. Subtract: 8a = 16 => a = 2, b = 1.', 'MEDIUM', true),
        ('12041111-0000-4000-8000-00000000003b', 'If x = a(cos t + t sin t) and y = a(sin t - t cos t), find d²y/dx² in terms of t (at t = π/4 as well). Also find dy/dx for y = (cos x)^x + cos⁻¹((1-x²)/(1+x²)), 0 < x < 1.', NULL, NULL, 'LA', 'Mathematics', 'Continuity and Differentiability', 5, 'Part 1: dx/dt = at cos t, dy/dt = at sin t => dy/dx = tan t => d²y/dx² = sec²t / (at cos t) = sec³t / (at) -> at π/4 = 8√2 / (πa) (2.5M). Part 2: (cos x)^x [ln cos x - x tan x] + 2/(1+x²) (2.5M).', 'Parametric 2nd deriv (2.5M) + Log+Trig deriv (2.5M)', NULL, 'Part 1: dx/dt = at cos t, dy/dt = at sin t => dy/dx = tan t => d²y/dx² = sec²t / (at cos t) = sec³t / (at) -> at π/4 = 8√2 / (πa) (2.5M). Part 2: (cos x)^x [ln cos x - x tan x] + 2/(1+x²) (2.5M).', 'HARD', true),
        ('12041111-0000-4000-8000-00000000003c', '(i) Check differentiability of f(x) = |x - 1| at x = 1. (ii) Differentiate sin⁻¹(2x/(1+x²)) w.r.t. x for |x| < 1. (iii) If y = 3e^(2x) + 2e^(3x), verify y'''' - 5y'' + 6y = 0. (iv) Value of k if f(x) = (1 - cos 4x)/(8x²) at x≠0 and k at x=0 is continuous at 0.', NULL, NULL, 'CASE', 'Mathematics', 'Continuity and Differentiability', 4, '(i) LHD = -1 ≠ RHD = +1 -> continuous but NOT differentiable at x=1. (ii) 2/(1+x²). (iii) Verified directly. (iv) lim (2 sin² 2x)/(8x²) = (8x²/8x²) = 1 -> k = 1.', '4 × 1M = 4M', 'High-speed rail track engineers enforce both continuity and first/second derivative smoothness across spline transitions so passenger jerk remains minimal.', '(i) LHD = -1 ≠ RHD = +1 -> continuous but NOT differentiable at x=1. (ii) 2/(1+x²). (iii) Verified directly. (iv) lim (2 sin² 2x)/(8x²) = (8x²/8x²) = 1 -> k = 1.', 'HARD', true),
        ('12041111-0000-4000-8000-00000000003d', 'Radius of a circle increases uniformly at 3 cm/s. Rate at which area increases when radius is 10 cm is:', '{"A":"30π cm²/s","B":"60π cm²/s","C":"100π cm²/s","D":"6π cm²/s"}'::jsonb, 'B', 'MCQ', 'Mathematics', 'Application of Derivatives', 1, 'dA/dt = 2πr (dr/dt) = 2π(10)(3) = 60π cm²/s.', NULL, NULL, 'dA/dt = 2πr (dr/dt) = 2π(10)(3) = 60π cm²/s.', 'EASY', true),
        ('12041111-0000-4000-8000-00000000003e', 'The function f(x) = e^x is strictly:', '{"A":"Decreasing on R","B":"Increasing on all of R","C":"Constant","D":"Neither increasing nor decreasing"}'::jsonb, 'B', 'MCQ', 'Mathematics', 'Application of Derivatives', 1, 'f''(x) = e^x > 0 for all x ∈ R.', NULL, NULL, 'f''(x) = e^x > 0 for all x ∈ R.', 'EASY', true),
        ('12041111-0000-4000-8000-00000000003f', 'Local minimum value of f(x) = 3 + |x| on R is:', '{"A":"0","B":"3 (at x = 0)","C":"1","D":"Does not exist"}'::jsonb, 'B', 'MCQ', 'Mathematics', 'Application of Derivatives', 1, '|x| ≥ 0 => minimum value is 3 at x = 0.', NULL, NULL, '|x| ≥ 0 => minimum value is 3 at x = 0.', 'EASY', true),
        ('12041111-0000-4000-8000-000000000040', 'Total revenue from selling x units is R(x) = 3x² + 36x + 5. Marginal revenue at x = 15 is:', '{"A":"96","B":"126","C":"116","D":"90"}'::jsonb, 'B', 'MCQ', 'Mathematics', 'Application of Derivatives', 1, 'MR = R''(x) = 6x + 36 => 6(15)+36 = 126.', NULL, NULL, 'MR = R''(x) = 6x + 36 => 6(15)+36 = 126.', 'EASY', true),
        ('12041111-0000-4000-8000-000000000041', 'Interval in which f(x) = x² - 4x + 6 is strictly decreasing is:', '{"A":"(2, ∞)","B":"(-∞, 2)","C":"(-∞, ∞)","D":"(0, 2)"}'::jsonb, 'B', 'MCQ', 'Mathematics', 'Application of Derivatives', 1, 'f''(x) = 2x - 4 < 0 => x < 2.', NULL, NULL, 'f''(x) = 2x - 4 < 0 => x < 2.', 'EASY', true),
        ('12041111-0000-4000-8000-000000000042', 'Assertion (A): If f''(c) = 0 and f''''(c) < 0 at an interior point c, then x = c is a point of local maximum.
Reason (R): Negative second derivative implies concavity downward at the stationary horizontal tangent.
Choose the correct option:
A) Both A and R are true, and R is the correct explanation of A.
B) Both A and R are true, and R is not the correct explanation of A.
C) A is true but R is false.
D) A is false but R is true.', '{"A":"Both A and R are true, and R is the correct explanation of A","B":"Both A and R are true, and R is not the correct explanation of A","C":"A is true but R is false","D":"A is false but R is true"}'::jsonb, 'A', 'ASSERTION_REASON', 'Mathematics', 'Application of Derivatives', 1, 'Second Derivative Test criterion.', NULL, NULL, 'Second Derivative Test criterion.', 'EASY', true),
        ('12041111-0000-4000-8000-000000000043', 'Find the intervals in which f(x) = 2x³ - 3x² - 36x + 7 is strictly increasing.', NULL, NULL, 'VSA', 'Mathematics', 'Application of Derivatives', 2, 'f''(x) = 6(x² - x - 6) = 6(x-3)(x+2) > 0 => (-∞, -2) ∪ (3, ∞).', 'f''(x) factoring (1M) + Intervals (1M)', NULL, 'f''(x) = 6(x² - x - 6) = 6(x-3)(x+2) > 0 => (-∞, -2) ∪ (3, ∞).', 'MEDIUM', true),
        ('12041111-0000-4000-8000-000000000044', 'Find two positive numbers whose sum is 16 and sum of whose cubes is minimum.', NULL, NULL, 'VSA', 'Mathematics', 'Application of Derivatives', 2, 'S = x³ + (16-x)³ -> S''(x) = 3x² - 3(16-x)² = 0 => x = 16-x => x = 8, y = 8 (S''''(8) > 0).', 'Derivative (1M) + 8, 8 (1M)', NULL, 'S = x³ + (16-x)³ -> S''(x) = 3x² - 3(16-x)² = 0 => x = 16-x => x = 8, y = 8 (S''''(8) > 0).', 'MEDIUM', true),
        ('12041111-0000-4000-8000-000000000045', 'A ladder 5 m long is leaning against a wall. The bottom is pulled along the ground at 2 cm/s. How fast is its height on the wall decreasing when the foot is 4 m from the wall?', NULL, NULL, 'SA', 'Mathematics', 'Application of Derivatives', 3, 'x² + y² = 25 -> at x=4, y=3. 2x dx/dt + 2y dy/dt = 0 => dy/dt = -(4/3)(2) = -8/3 cm/s (decreasing at 8/3 cm/s).', 'Relation & diff (1.5M) + 8/3 cm/s (1.5M)', NULL, 'x² + y² = 25 -> at x=4, y=3. 2x dx/dt + 2y dy/dt = 0 => dy/dt = -(4/3)(2) = -8/3 cm/s (decreasing at 8/3 cm/s).', 'MEDIUM', true),
        ('12041111-0000-4000-8000-000000000046', 'Find the absolute maximum and absolute minimum values of f(x) = sin x + cos x on [0, π].', NULL, NULL, 'SA', 'Mathematics', 'Application of Derivatives', 3, 'f''(x) = cos x - sin x = 0 => x = π/4. f(0)=1, f(π/4)=√2, f(π)=-1. Abs Max = √2, Abs Min = -1.', 'Critical point (1.5M) + √2 & -1 (1.5M)', NULL, 'f''(x) = cos x - sin x = 0 => x = π/4. f(0)=1, f(π/4)=√2, f(π)=-1. Abs Max = √2, Abs Min = -1.', 'MEDIUM', true),
        ('12041111-0000-4000-8000-000000000047', 'Prove that the volume of the largest cone that can be inscribed in a sphere of radius R is 8/27 of the volume of the sphere.', NULL, NULL, 'LA', 'Mathematics', 'Application of Derivatives', 5, 'Let cone centre-to-base distance be x -> h = R + x, base radius r² = R² - x². V(x) = (1/3)π(R²-x²)(R+x). dV/dx = (π/3)[(R²-x²) - 2x(R+x)] = (π/3)(R+x)(R - 3x) = 0 => x = R/3. V''''(R/3) < 0. Max V = (1/3)π(8R²/9)(4R/3) = (8/27) × (4/3)πR³.', 'Geometry & V(x) (2M) + x=R/3 & 2nd deriv (2M) + 8/27 proof (1M)', NULL, 'Let cone centre-to-base distance be x -> h = R + x, base radius r² = R² - x². V(x) = (1/3)π(R²-x²)(R+x). dV/dx = (π/3)[(R²-x²) - 2x(R+x)] = (π/3)(R+x)(R - 3x) = 0 => x = R/3. V''''(R/3) < 0. Max V = (1/3)π(8R²/9)(4R/3) = (8/27) × (4/3)πR³.', 'HARD', true),
        ('12041111-0000-4000-8000-000000000048', '(i) Express perimeter P = 2x + 2y + πx (if semicircle sits on rectangle width 2x = x'') cleanly for a Norman window of perimeter 10 m: write area A(x). (ii) Value of x maximising sunlight admitted through the window. (iii) Sand pouring at 12 cm³/s forms cone with h = (1/6)r: find dh/dt when h=4 cm. (iv) Interval where y = x² e^(-x) increases.', NULL, NULL, 'CASE', 'Mathematics', 'Application of Derivatives', 4, '(i) P = 2r + 2h + πr = 10 -> A = 2rh + ½πr² = r(10 - 2r - πr) + ½πr² = 10r - 2r² - ½πr². (ii) r = 10/(π + 4) m. (iii) V = 12π h³ -> dV/dt = 36π h² dh/dt => dh/dt = 12/(36π×16) = 1/(48π) cm/s. (iv) [0, 2].', '4 × 1M = 4M', 'Packaging engineers minimise tin-sheet surface area for fixed-volume cylindrical cans while architects maximise daylight entry through Norman window curves.', '(i) P = 2r + 2h + πr = 10 -> A = 2rh + ½πr² = r(10 - 2r - πr) + ½πr² = 10r - 2r² - ½πr². (ii) r = 10/(π + 4) m. (iii) V = 12π h³ -> dV/dt = 36π h² dh/dt => dh/dt = 12/(36π×16) = 1/(48π) cm/s. (iv) [0, 2].', 'HARD', true),
        ('12041111-0000-4000-8000-000000000049', '∫ e^x [f(x) + f''(x)] dx equals:', '{"A":"e^x f''(x) + C","B":"e^x f(x) + C","C":"e^x + f(x) + C","D":"f(x) + C"}'::jsonb, 'B', 'MCQ', 'Mathematics', 'Integrals', 1, 'Classic standard identity via integration by parts.', NULL, NULL, 'Classic standard identity via integration by parts.', 'EASY', true),
        ('12041111-0000-4000-8000-00000000004a', '∫₋ₐᵃ f(x) dx equals 0 whenever f(x) is:', '{"A":"Even function","B":"Odd function (f(-x) = -f(x))","C":"Periodic","D":"Positive"}'::jsonb, 'B', 'MCQ', 'Mathematics', 'Integrals', 1, 'Symmetric opposite areas cancel out.', NULL, NULL, 'Symmetric opposite areas cancel out.', 'EASY', true),
        ('12041111-0000-4000-8000-00000000004b', '∫ (1 / (x² + a²)) dx equals:', '{"A":"tan⁻¹(x/a) + C","B":"(1/a) tan⁻¹(x/a) + C","C":"sin⁻¹(x/a) + C","D":"(1/2a) ln|(x-a)/(x+a)| + C"}'::jsonb, 'B', 'MCQ', 'Mathematics', 'Integrals', 1, '(1/a) tan⁻¹(x/a) + C.', NULL, NULL, '(1/a) tan⁻¹(x/a) + C.', 'EASY', true),
        ('12041111-0000-4000-8000-00000000004c', 'Value of ∫₀^(π/2) [√(sin x) / (√(sin x) + √(cos x))] dx is:', '{"A":"π/2","B":"π/4","C":"0","D":"1"}'::jsonb, 'B', 'MCQ', 'Mathematics', 'Integrals', 1, 'King''s property P₄: 2I = ∫₀^(π/2) 1 dx = π/2 => I = π/4.', NULL, NULL, 'King''s property P₄: 2I = ∫₀^(π/2) 1 dx = π/2 => I = π/4.', 'EASY', true),
        ('12041111-0000-4000-8000-00000000004d', '∫ dx / √(9 - x²) equals:', '{"A":"sin⁻¹(x/3) + C","B":"cos⁻¹(x/3) + C","C":"(1/3) sin⁻¹(x/3) + C","D":"tan⁻¹(x/3) + C"}'::jsonb, 'A', 'MCQ', 'Mathematics', 'Integrals', 1, 'Standard sin⁻¹(x/a) + C.', NULL, NULL, 'Standard sin⁻¹(x/a) + C.', 'EASY', true),
        ('12041111-0000-4000-8000-00000000004e', 'Assertion (A): Value of ∫_{-π/2}^{π/2} sin⁷ x dx is zero.
Reason (R): f(x) = sin⁷ x is an odd continuous function over symmetric limits [-π/2, π/2].
Choose the correct option:
A) Both A and R are true, and R is the correct explanation of A.
B) Both A and R are true, and R is not the correct explanation of A.
C) A is true but R is false.
D) A is false but R is true.', '{"A":"Both A and R are true, and R is the correct explanation of A","B":"Both A and R are true, and R is not the correct explanation of A","C":"A is true but R is false","D":"A is false but R is true"}'::jsonb, 'A', 'ASSERTION_REASON', 'Mathematics', 'Integrals', 1, 'Symmetric integral of odd function = 0.', NULL, NULL, 'Symmetric integral of odd function = 0.', 'EASY', true),
        ('12041111-0000-4000-8000-00000000004f', 'Evaluate: ∫ e^x [1/x - 1/x²] dx.', NULL, NULL, 'VSA', 'Mathematics', 'Integrals', 2, 'Since d/dx(1/x) = -1/x², integral = e^x / x + C.', '2M', NULL, 'Since d/dx(1/x) = -1/x², integral = e^x / x + C.', 'MEDIUM', true),
        ('12041111-0000-4000-8000-000000000050', 'Evaluate: ∫ (cos 2x + 2 sin² x) / cos² x dx.', NULL, NULL, 'VSA', 'Mathematics', 'Integrals', 2, 'cos 2x + 2 sin²x = 1 => ∫ sec² x dx = tan x + C.', 'Trig identity (1M) + tan x + C (1M)', NULL, 'cos 2x + 2 sin²x = 1 => ∫ sec² x dx = tan x + C.', 'MEDIUM', true),
        ('12041111-0000-4000-8000-000000000051', 'Evaluate using partial fractions: ∫ x / [(x - 1)(x - 2)] dx.', NULL, NULL, 'SA', 'Mathematics', 'Integrals', 3, 'A/(x-1) + B/(x-2) => A = -1, B = 2 -> 2 ln|x - 2| - ln|x - 1| + C.', 'Partial fractions (1.5M) + Integral (1.5M)', NULL, 'A/(x-1) + B/(x-2) => A = -1, B = 2 -> 2 ln|x - 2| - ln|x - 1| + C.', 'MEDIUM', true),
        ('12041111-0000-4000-8000-000000000052', 'Evaluate: ∫₀^π [x sin x / (1 + cos² x)] dx.', NULL, NULL, 'SA', 'Mathematics', 'Integrals', 3, 'By King''s property P₄: 2I = π ∫₀^π [sin x/(1+cos²x)] dx -> put cos x = t => 2I = π [ -tan⁻¹ t ]₁⁻¹ = π(π/2) => I = π² / 4.', 'King''s prop (1.5M) + π²/4 (1.5M)', NULL, 'By King''s property P₄: 2I = π ∫₀^π [sin x/(1+cos²x)] dx -> put cos x = t => 2I = π [ -tan⁻¹ t ]₁⁻¹ = π(π/2) => I = π² / 4.', 'MEDIUM', true),
        ('12041111-0000-4000-8000-000000000053', 'Evaluate: ∫₀^(π/4) log(1 + tan x) dx using definite integral properties. Also evaluate ∫ (3x + 5) / √(x² + 2x + 3) dx.', NULL, NULL, 'LA', 'Mathematics', 'Integrals', 5, 'Part 1: P₄ -> log(1 + (1-tan x)/(1+tan x)) = log(2/(1+tan x)) => 2I = (π/4) log 2 => I = (π/8) log 2 (2.5M). Part 2: 3x+5 = (3/2)(2x+2) + 2 -> 3√(x²+2x+3) + 2 ln|(x+1)+√(x²+2x+3)| + C (2.5M).', 'Definite integral (π/8)log 2 (2.5M) + Indefinite (2.5M)', NULL, 'Part 1: P₄ -> log(1 + (1-tan x)/(1+tan x)) = log(2/(1+tan x)) => 2I = (π/4) log 2 => I = (π/8) log 2 (2.5M). Part 2: 3x+5 = (3/2)(2x+2) + 2 -> 3√(x²+2x+3) + 2 ln|(x+1)+√(x²+2x+3)| + C (2.5M).', 'HARD', true),
        ('12041111-0000-4000-8000-000000000054', '(i) Evaluate ∫ x e^x / (1 + x)² dx. (ii) Evaluate ∫_{-1}^2 |x³ - x| dx? Easier 1M: ∫₀^1 |2x - 1| dx. (iii) Evaluate ∫ dx / (e^x + e^(-x)). (iv) State King''s Property ∫₀ᵃ f(x) dx = ...', NULL, NULL, 'CASE', 'Mathematics', 'Integrals', 4, '(i) Write x = (x+1)-1 -> e^x / (x+1) + C. (ii) Split at 1/2: 1/4 + 1/4 = 1/2. (iii) ∫ e^x/(e^(2x)+1) dx = tan⁻¹(e^x) + C. (iv) ∫₀ᵃ f(a - x) dx.', '4 × 1M = 4M', 'Signal engineers compute continuous AC energy averages and cumulative impulse areas using King''s symmetry property and rational substitution integrals.', '(i) Write x = (x+1)-1 -> e^x / (x+1) + C. (ii) Split at 1/2: 1/4 + 1/4 = 1/2. (iii) ∫ e^x/(e^(2x)+1) dx = tan⁻¹(e^x) + C. (iv) ∫₀ᵃ f(a - x) dx.', 'HARD', true),
        ('12041111-0000-4000-8000-000000000055', 'Area enclosed by the circle x² + y² = a² is:', '{"A":"2πa","B":"πa²","C":"½πa²","D":"4πa²"}'::jsonb, 'B', 'MCQ', 'Mathematics', 'Application of Integrals', 1, '4 ∫₀ᵃ √(a²-x²) dx = πa².', NULL, NULL, '4 ∫₀ᵃ √(a²-x²) dx = πa².', 'EASY', true),
        ('12041111-0000-4000-8000-000000000056', 'Area bounded by parabola y = x², x-axis, and lines x = 0 to x = 3 is:', '{"A":"3 sq units","B":"9 sq units","C":"27 sq units","D":"9/2 sq units"}'::jsonb, 'B', 'MCQ', 'Mathematics', 'Application of Integrals', 1, '∫₀³ x² dx = [x³/3]₀³ = 9.', NULL, NULL, '∫₀³ x² dx = [x³/3]₀³ = 9.', 'EASY', true),
        ('12041111-0000-4000-8000-000000000057', 'Area enclosed by the ellipse x²/16 + y²/9 = 1 is:', '{"A":"12π","B":"24π","C":"6π","D":"48π"}'::jsonb, 'A', 'MCQ', 'Mathematics', 'Application of Integrals', 1, 'πab = π(4)(3) = 12π sq units.', NULL, NULL, 'πab = π(4)(3) = 12π sq units.', 'EASY', true),
        ('12041111-0000-4000-8000-000000000058', 'Area bounded by curve y = cos x, x-axis between x = 0 and x = π is:', '{"A":"0","B":"2 sq units","C":"1 sq unit","D":"4 sq units"}'::jsonb, 'B', 'MCQ', 'Mathematics', 'Application of Integrals', 1, '∫₀^(π/2) cos x dx + |∫_{π/2}^π cos x dx| = 1 + 1 = 2 sq units.', NULL, NULL, '∫₀^(π/2) cos x dx + |∫_{π/2}^π cos x dx| = 1 + 1 = 2 sq units.', 'EASY', true),
        ('12041111-0000-4000-8000-000000000059', 'Area of the smaller region bounded by x² + y² = 4 and line x = 1 is:', '{"A":"2π/3 - √3","B":"4π/3 - √3","C":"π - √3","D":"4π/3"}'::jsonb, 'B', 'MCQ', 'Mathematics', 'Application of Integrals', 1, '2 ∫₁² √(4-x²) dx = [x√(4-x²)+4 sin⁻¹(x/2)]₁² = 2π - (√3 + 2π/3) = 4π/3 - √3.', NULL, NULL, '2 ∫₁² √(4-x²) dx = [x√(4-x²)+4 sin⁻¹(x/2)]₁² = 2π - (√3 + 2π/3) = 4π/3 - √3.', 'EASY', true),
        ('12041111-0000-4000-8000-00000000005a', 'Assertion (A): When calculating geometric area below the x-axis from x=a to x=b, we take the absolute value |∫ y dx|.
Reason (R): Geometric area is strictly non-negative, whereas the definite integral below the x-axis yields a negative signed value.
Choose the correct option:
A) Both A and R are true, and R is the correct explanation of A.
B) Both A and R are true, and R is not the correct explanation of A.
C) A is true but R is false.
D) A is false but R is true.', '{"A":"Both A and R are true, and R is the correct explanation of A","B":"Both A and R are true, and R is not the correct explanation of A","C":"A is true but R is false","D":"A is false but R is true"}'::jsonb, 'A', 'ASSERTION_REASON', 'Mathematics', 'Application of Integrals', 1, 'Prevents positive and negative lobe cancellation.', NULL, NULL, 'Prevents positive and negative lobe cancellation.', 'EASY', true),
        ('12041111-0000-4000-8000-00000000005b', 'Find area bounded by curve y² = 4x, y-axis, and the line y = 3.', NULL, NULL, 'VSA', 'Mathematics', 'Application of Integrals', 2, '∫₀³ (y²/4) dy = [y³/12]₀³ = 27/12 = 9/4 sq units.', 'Integral setup (1M) + 9/4 (1M)', NULL, '∫₀³ (y²/4) dy = [y³/12]₀³ = 27/12 = 9/4 sq units.', 'MEDIUM', true),
        ('12041111-0000-4000-8000-00000000005c', 'Find area of region bounded by y = |x| and y = 2? Or bounded by x² = 4y, y = 2, y = 4, and y-axis in 1st quadrant.', NULL, NULL, 'VSA', 'Mathematics', 'Application of Integrals', 2, '∫₂⁴ 2√y dy = (4/3)[y^(3/2)]₂⁴ = (4/3)(8 - 2√2) = (32 - 8√2)/3 sq units.', '2M', NULL, '∫₂⁴ 2√y dy = (4/3)[y^(3/2)]₂⁴ = (4/3)(8 - 2√2) = (32 - 8√2)/3 sq units.', 'MEDIUM', true),
        ('12041111-0000-4000-8000-00000000005d', 'Using integration, find the area of the region bounded by the triangle whose vertices are (-1, 0), (1, 3), and (3, 2).', NULL, NULL, 'SA', 'Mathematics', 'Application of Integrals', 3, 'Equations: AB: y = (3/2)(x+1); BC: y = -(1/2)(x-7); AC: y = (1/2)(x+1). Area = ∫₋₁¹ AB + ∫₁³ BC - ∫₋₁³ AC = 3 + 5 - 4 = 4 sq units.', 'Line equations (1.5M) + Integration 4 sq units (1.5M)', NULL, 'Equations: AB: y = (3/2)(x+1); BC: y = -(1/2)(x-7); AC: y = (1/2)(x+1). Area = ∫₋₁¹ AB + ∫₁³ BC - ∫₋₁³ AC = 3 + 5 - 4 = 4 sq units.', 'MEDIUM', true),
        ('12041111-0000-4000-8000-00000000005e', 'Find the area of the region bounded by the curve y = x² and the line y = 4.', NULL, NULL, 'SA', 'Mathematics', 'Application of Integrals', 3, 'Symmetric about y-axis -> 2 ∫₀⁴ √y dy = (4/3)[8] = 32/3 sq units.', 'Sketch & limits (1M) + 32/3 (2M)', NULL, 'Symmetric about y-axis -> 2 ∫₀⁴ √y dy = (4/3)[8] = 32/3 sq units.', 'MEDIUM', true),
        ('12041111-0000-4000-8000-00000000005f', 'Using integration, find the area of the smaller region enclosed between the ellipse x²/9 + y²/4 = 1 and the line x/3 + y/2 = 1. Also find the area bounded by the circle x² + y² = 16 exterior to? Keep rationalized NCERT: find area enclosed by x² + y² = 16 and x-axis from x = 0 to x = 4 in 1st quadrant + ellipse/line.', NULL, NULL, 'LA', 'Mathematics', 'Application of Integrals', 5, 'Ellipse & line meet at (3,0) and (0,2): Area = ∫₀³ [2√(1-x²/9) - 2(1-x/3)] dx = [(3×2π)/4 - (1/2)(3×2)] = (3π/2 - 3) = (3/2)(π - 2) sq units (3.5M). Quarter circle x²+y²=16 -> π(16)/4 = 4π sq units (1.5M).', 'Ellipse-line area (3.5M) + Quarter circle 4π (1.5M)', NULL, 'Ellipse & line meet at (3,0) and (0,2): Area = ∫₀³ [2√(1-x²/9) - 2(1-x/3)] dx = [(3×2π)/4 - (1/2)(3×2)] = (3π/2 - 3) = (3/2)(π - 2) sq units (3.5M). Quarter circle x²+y²=16 -> π(16)/4 = 4π sq units (1.5M).', 'HARD', true),
        ('12041111-0000-4000-8000-000000000060', '(i) Integral formula for area bounded by circle x² + y² = 9 in 1st quadrant. (ii) Area under y = sin x from x = 0 to x = 2π (total geometric area). (iii) Area bounded by line y = 2x + 3, x-axis, x=0, x=2. (iv) Area between y = |x + 3| and x-axis from x = -6 to x = 0.', NULL, NULL, 'CASE', 'Mathematics', 'Application of Integrals', 4, '(i) ∫₀³ √(9-x²) dx = 9π/4. (ii) 2 ∫₀^π sin x dx = 4 sq units. (iii) [x²+3x]₀² = 10 sq units. (iv) Two triangles: ½(3)(3) + ½(3)(3) = 9 sq units.', '4 × 1M = 4M', 'Civil architects compute cross-sectional arch vault areas and curved parabolic roof profiles using bounded definite integration strips.', '(i) ∫₀³ √(9-x²) dx = 9π/4. (ii) 2 ∫₀^π sin x dx = 4 sq units. (iii) [x²+3x]₀² = 10 sq units. (iv) Two triangles: ½(3)(3) + ½(3)(3) = 9 sq units.', 'HARD', true),
        ('12041111-0000-4000-8000-000000000061', 'Order and Degree respectively of differential equation (d²y/dx²)³ + (dy/dx)² + sin(dy/dx) + 1 = 0 are:', '{"A":"2 and 3","B":"2 and Not Defined (due to sin(dy/dx) non-polynomial term)","C":"3 and 2","D":"1 and Not Defined"}'::jsonb, 'B', 'MCQ', 'Mathematics', 'Differential Equations', 1, 'Highest derivative = 2; transcendent sin(y'') makes degree undefined.', NULL, NULL, 'Highest derivative = 2; transcendent sin(y'') makes degree undefined.', 'EASY', true),
        ('12041111-0000-4000-8000-000000000062', 'Integrating Factor (IF) of the linear differential equation dy/dx + y tan x = sec x is:', '{"A":"cos x","B":"sec x","C":"tan x","D":"sin x"}'::jsonb, 'B', 'MCQ', 'Mathematics', 'Differential Equations', 1, 'e^(∫ tan x dx) = e^(ln sec x) = sec x.', NULL, NULL, 'e^(∫ tan x dx) = e^(ln sec x) = sec x.', 'EASY', true),
        ('12041111-0000-4000-8000-000000000063', 'Number of arbitrary constants in the general solution of a differential equation of 4th order is:', '{"A":"0","B":"3","C":"4","D":"5"}'::jsonb, 'C', 'MCQ', 'Mathematics', 'Differential Equations', 1, 'General solution has constants equal to order (particular solution has 0).', NULL, NULL, 'General solution has constants equal to order (particular solution has 0).', 'EASY', true),
        ('12041111-0000-4000-8000-000000000064', 'Differential equation of family of circles passing through origin with centre on x-axis contains how many arbitrary constants?', '{"A":"1","B":"2","C":"3","D":"0"}'::jsonb, 'A', 'MCQ', 'Mathematics', 'Differential Equations', 1, 'x² + y² - 2ax = 0 has only 1 parameter a -> 1st order ODE.', NULL, NULL, 'x² + y² - 2ax = 0 has only 1 parameter a -> 1st order ODE.', 'EASY', true),
        ('12041111-0000-4000-8000-000000000065', 'General solution of dy/dx = e^(x - y) is:', '{"A":"e^y = e^x + C","B":"e^(-y) = e^x + C","C":"y = e^x + C","D":"e^(x+y) = C"}'::jsonb, 'A', 'MCQ', 'Mathematics', 'Differential Equations', 1, '∫ e^y dy = ∫ e^x dx => e^y = e^x + C.', NULL, NULL, '∫ e^y dy = ∫ e^x dx => e^y = e^x + C.', 'EASY', true),
        ('12041111-0000-4000-8000-000000000066', 'Assertion (A): The differential equation x dy/dx + 2y = x² is a first-order linear differential equation.
Reason (R): Dividing by x reduces it cleanly to standard form dy/dx + P(x)y = Q(x) with P=2/x and Q=x.
Choose the correct option:
A) Both A and R are true, and R is the correct explanation of A.
B) Both A and R are true, and R is not the correct explanation of A.
C) A is true but R is false.
D) A is false but R is true.', '{"A":"Both A and R are true, and R is the correct explanation of A","B":"Both A and R are true, and R is not the correct explanation of A","C":"A is true but R is false","D":"A is false but R is true"}'::jsonb, 'A', 'ASSERTION_REASON', 'Mathematics', 'Differential Equations', 1, 'Matches dy/dx + Py = Q cleanly.', NULL, NULL, 'Matches dy/dx + Py = Q cleanly.', 'EASY', true),
        ('12041111-0000-4000-8000-000000000067', 'Solve the separable differential equation: sec² x tan y dx + sec² y tan x dy = 0.', NULL, NULL, 'VSA', 'Mathematics', 'Differential Equations', 2, 'Divide by tan x tan y: ∫ (sec²x/tan x) dx + ∫ (sec²y/tan y) dy = 0 => ln|tan x tan y| = ln C => tan x tan y = C.', 'Separation (1M) + tan x tan y = C (1M)', NULL, 'Divide by tan x tan y: ∫ (sec²x/tan x) dx + ∫ (sec²y/tan y) dy = 0 => ln|tan x tan y| = ln C => tan x tan y = C.', 'MEDIUM', true),
        ('12041111-0000-4000-8000-000000000068', 'Find Integrating Factor of (1 + y²) dx = (tan⁻¹ y - x) dy.', NULL, NULL, 'VSA', 'Mathematics', 'Differential Equations', 2, 'dx/dy + x/(1+y²) = (tan⁻¹ y)/(1+y²) -> IF = e^(∫ 1/(1+y²) dy) = e^(tan⁻¹ y).', 'Standard dx/dy form (1M) + IF (1M)', NULL, 'dx/dy + x/(1+y²) = (tan⁻¹ y)/(1+y²) -> IF = e^(∫ 1/(1+y²) dy) = e^(tan⁻¹ y).', 'MEDIUM', true),
        ('12041111-0000-4000-8000-000000000069', 'Solve the homogeneous differential equation: (x² - y²) dx + 2xy dy = 0.', NULL, NULL, 'SA', 'Mathematics', 'Differential Equations', 3, 'dy/dx = (y² - x²)/(2xy). Put y = vx => v + x dv/dx = (v²-1)/(2v) => x dv/dx = -(1+v²)/(2v) => ∫ 2v/(1+v²) dv = -∫ dx/x => ln(1+y²/x²) = ln(C/x) => x² + y² = Cx.', 'Homogeneous y=vx (1.5M) + Solution x²+y²=Cx (1.5M)', NULL, 'dy/dx = (y² - x²)/(2xy). Put y = vx => v + x dv/dx = (v²-1)/(2v) => x dv/dx = -(1+v²)/(2v) => ∫ 2v/(1+v²) dv = -∫ dx/x => ln(1+y²/x²) = ln(C/x) => x² + y² = Cx.', 'MEDIUM', true),
        ('12041111-0000-4000-8000-00000000006a', 'Find the particular solution of dy/dx + y cot x = 2x + x² cot x, given y = 0 when x = π/2.', NULL, NULL, 'SA', 'Mathematics', 'Differential Equations', 3, 'IF = e^(∫ cot x dx) = sin x. y sin x = ∫ (2x sin x + x² cos x) dx = x² sin x + C. At (π/2, 0): 0 = π²/4 + C => y = x² - π² / (4 sin x).', 'IF sin x (1M) + Solution & C (2M)', NULL, 'IF = e^(∫ cot x dx) = sin x. y sin x = ∫ (2x sin x + x² cos x) dx = x² sin x + C. At (π/2, 0): 0 = π²/4 + C => y = x² - π² / (4 sin x).', 'MEDIUM', true),
        ('12041111-0000-4000-8000-00000000006b', 'Solve the linear differential equation: (1 + x²) dy/dx + 2xy = 1 / (1 + x²), given y = 0 when x = 1. Also verify that y = a cos x + b sin x is a solution of d²y/dx² + y = 0 and solve (x dy - y dx) y sin(y/x) = (y dx + x dy) x cos(y/x) or dy/dx = (x+y+1)/(...) -> keep homogeneous x cos(y/x) dy/dx = y cos(y/x) + x.', NULL, NULL, 'LA', 'Mathematics', 'Differential Equations', 5, 'Part 1: dy/dx + 2x/(1+x²) y = 1/(1+x²)² -> IF = 1 + x². y(1+x²) = ∫ dx/(1+x²) = tan⁻¹ x + C. At x=1, y=0 -> C = -π/4 => y(1+x²) = tan⁻¹ x - π/4 (3M). Part 2: y''=-a sin x+b cos x, y''''=-y => y''''+y=0 verified (2M).', 'Linear ODE particular sol (3M) + Verification (2M)', NULL, 'Part 1: dy/dx + 2x/(1+x²) y = 1/(1+x²)² -> IF = 1 + x². y(1+x²) = ∫ dx/(1+x²) = tan⁻¹ x + C. At x=1, y=0 -> C = -π/4 => y(1+x²) = tan⁻¹ x - π/4 (3M). Part 2: y''=-a sin x+b cos x, y''''=-y => y''''+y=0 verified (2M).', 'HARD', true),
        ('12041111-0000-4000-8000-00000000006c', '(i) Form ODE of family of parabolas y² = 4ax. (ii) Exponential bacteria growth model dN/dt = kN: if count doubles from 1000 to 2000 in 2 hours, find k. (iii) Order & degree of (d³y/dx³)² + y'' + y = 0. (iv) Solution of dy/dx = (1 + y²)/(1 + x²).', NULL, NULL, 'CASE', 'Mathematics', 'Differential Equations', 4, '(i) 2yy'' = 4a => a = yy''/2 => y = 2xy''. (ii) e^(2k) = 2 => k = (ln 2)/2. (iii) Order 3, Degree 2. (iv) tan⁻¹ y = tan⁻¹ x + C.', '4 × 1M = 4M', 'Biomedical pharmacokinetics and RL electrical circuits use first-order linear and separable differential equations to model exponential concentration decay over time.', '(i) 2yy'' = 4a => a = yy''/2 => y = 2xy''. (ii) e^(2k) = 2 => k = (ln 2)/2. (iii) Order 3, Degree 2. (iv) tan⁻¹ y = tan⁻¹ x + C.', 'HARD', true),
        ('12041111-0000-4000-8000-00000000006d', 'If a = 2î - ĵ + 2k̂, unit vector in the direction of a is:', '{"A":"(2î - ĵ + 2k̂)/9","B":"(2î - ĵ + 2k̂)/3","C":"(2î + ĵ + 2k̂)/3","D":"2î - ĵ + 2k̂"}'::jsonb, 'B', 'MCQ', 'Mathematics', 'Vector Algebra', 1, '|a| = √(4+1+4) = 3.', NULL, NULL, '|a| = √(4+1+4) = 3.', 'EASY', true),
        ('12041111-0000-4000-8000-00000000006e', 'Projection of vector a = 2î + 3ĵ + 2k̂ on vector b = î + 2ĵ + k̂ is:', '{"A":"10 / √6","B":"10 / √17","C":"6 / √10","D":"5 / √6"}'::jsonb, 'A', 'MCQ', 'Mathematics', 'Vector Algebra', 1, '(a·b)/|b| = (2+6+2)/√(1+4+1) = 10/√6.', NULL, NULL, '(a·b)/|b| = (2+6+2)/√(1+4+1) = 10/√6.', 'EASY', true),
        ('12041111-0000-4000-8000-00000000006f', 'Value of î·(ĵ × k̂) + ĵ·(î × k̂) + k̂·(î × ĵ) is:', '{"A":"3","B":"1","C":"-1","D":"0"}'::jsonb, 'B', 'MCQ', 'Mathematics', 'Vector Algebra', 1, '1 + (-1) + 1 = 1.', NULL, NULL, '1 + (-1) + 1 = 1.', 'EASY', true),
        ('12041111-0000-4000-8000-000000000070', 'If |a| = 10, |b| = 2, and a·b = 12, then |a × b| equals:', '{"A":"16","B":"20","C":"12","D":"8"}'::jsonb, 'A', 'MCQ', 'Mathematics', 'Vector Algebra', 1, '|a×b|² = |a|²|b|² - (a·b)² = 400 - 144 = 256 => 16.', NULL, NULL, '|a×b|² = |a|²|b|² - (a·b)² = 400 - 144 = 256 => 16.', 'EASY', true),
        ('12041111-0000-4000-8000-000000000071', 'Area of parallelogram whose adjacent sides are vectors a and b is:', '{"A":"½ |a × b|","B":"|a × b|","C":"|a · b|","D":"2 |a × b|"}'::jsonb, 'B', 'MCQ', 'Mathematics', 'Vector Algebra', 1, 'Parallelogram = |a×b|; Triangle = ½|a×b|.', NULL, NULL, 'Parallelogram = |a×b|; Triangle = ½|a×b|.', 'EASY', true),
        ('12041111-0000-4000-8000-000000000072', 'Assertion (A): If a + b + c = 0 for three unit vectors a, b, c, then a·b + b·c + c·a = -3/2.
Reason (R): Squaring |a+b+c|² = |a|² + |b|² + |c|² + 2(a·b+b·c+c·a) = 0 gives 3 + 2Σ(a·b) = 0.
Choose the correct option:
A) Both A and R are true, and R is the correct explanation of A.
B) Both A and R are true, and R is not the correct explanation of A.
C) A is true but R is false.
D) A is false but R is true.', '{"A":"Both A and R are true, and R is the correct explanation of A","B":"Both A and R are true, and R is not the correct explanation of A","C":"A is true but R is false","D":"A is false but R is true"}'::jsonb, 'A', 'ASSERTION_REASON', 'Mathematics', 'Vector Algebra', 1, 'Direct dot-product identity.', NULL, NULL, 'Direct dot-product identity.', 'EASY', true),
        ('12041111-0000-4000-8000-000000000073', 'Find λ if vectors a = 2î + λĵ + k̂ and b = î - 2ĵ + 3k̂ are perpendicular.', NULL, NULL, 'VSA', 'Mathematics', 'Vector Algebra', 2, 'a·b = 2 - 2λ + 3 = 0 => λ = 5/2.', '2M', NULL, 'a·b = 2 - 2λ + 3 = 0 => λ = 5/2.', 'MEDIUM', true),
        ('12041111-0000-4000-8000-000000000074', 'Find a vector of magnitude 7 units in the direction of a = î - 2ĵ + 2k̂.', NULL, NULL, 'VSA', 'Mathematics', 'Vector Algebra', 2, '|a| = 3 -> 7 â = (7/3)(î - 2ĵ + 2k̂).', '2M', NULL, '|a| = 3 -> 7 â = (7/3)(î - 2ĵ + 2k̂).', 'MEDIUM', true),
        ('12041111-0000-4000-8000-000000000075', 'Find a unit vector perpendicular to EACH of the vectors (a + b) and (a - b), where a = 3î + 2ĵ + 2k̂ and b = î + 2ĵ - 2k̂.', NULL, NULL, 'SA', 'Mathematics', 'Vector Algebra', 3, 'a+b = 4î+4ĵ; a-b = 2î+4k̂. (a+b)×(a-b) = 16î - 16ĵ - 8k̂ (magnitude 24) -> ±(2î - 2ĵ - k̂)/3.', 'Cross product (2M) + Unit vector (1M)', NULL, 'a+b = 4î+4ĵ; a-b = 2î+4k̂. (a+b)×(a-b) = 16î - 16ĵ - 8k̂ (magnitude 24) -> ±(2î - 2ĵ - k̂)/3.', 'MEDIUM', true),
        ('12041111-0000-4000-8000-000000000076', 'If a, b, c are mutually perpendicular vectors of equal magnitudes, show that vector (a + b + c) is equally inclined to a, b, and c.', NULL, NULL, 'SA', 'Mathematics', 'Vector Algebra', 3, '|a|=|b|=|c|=k. (a+b+c)·a = k² => cos α = k² / (|a+b+c|·k) = 1/√3 -> identical cos β = cos γ = 1/√3.', 'Proof (3M)', NULL, '|a|=|b|=|c|=k. (a+b+c)·a = k² => cos α = k² / (|a+b+c|·k) = 1/√3 -> identical cos β = cos γ = 1/√3.', 'MEDIUM', true),
        ('12041111-0000-4000-8000-000000000077', 'Let a = î + 4ĵ + 2k̂, b = 3î - 2ĵ + 7k̂, c = 2î - ĵ + 4k̂. Find a vector d which is perpendicular to both a and b, and c·d = 15. Also find area of triangle with vertices A(1, 1, 2), B(2, 3, 5), and C(1, 5, 5).', NULL, NULL, 'LA', 'Mathematics', 'Vector Algebra', 5, 'Part 1: a × b = 24î - ĵ - 10k̂; let d = λ(24î - ĵ - 10k̂). c·d = λ(48 + 1 - 40) = 9λ = 15 => λ = 5/3 -> d = (5/3)(24î - ĵ - 10k̂) (3M). Part 2: AB = î+2ĵ+3k̂, AC = 4ĵ+3k̂ -> AB×AC = -6î - 3ĵ + 4k̂ => Area = ½√(36+9+16) = ½√61 sq units (2M).', 'Vector d (3M) + Triangle area (2M)', NULL, 'Part 1: a × b = 24î - ĵ - 10k̂; let d = λ(24î - ĵ - 10k̂). c·d = λ(48 + 1 - 40) = 9λ = 15 => λ = 5/3 -> d = (5/3)(24î - ĵ - 10k̂) (3M). Part 2: AB = î+2ĵ+3k̂, AC = 4ĵ+3k̂ -> AB×AC = -6î - 3ĵ + 4k̂ => Area = ½√(36+9+16) = ½√61 sq units (2M).', 'HARD', true),
        ('12041111-0000-4000-8000-000000000078', '(i) Direction cosines of vector î + 2ĵ + 3k̂. (ii) Angle between two vectors a and b with |a|=√3, |b|=2, a·b=√6. (iii) Position vector of midpoint of P(2î+3ĵ+4k̂) and Q(4î+ĵ-2k̂). (iv) Value of (3a - 5b)·(2a + 7b) in expanded form.', NULL, NULL, 'CASE', 'Mathematics', 'Vector Algebra', 4, '(i) (1/√14, 2/√14, 3/√14). (ii) cos θ = √6/(2√3) = 1/√2 => 45°. (iii) 3î + 2ĵ + k̂. (iv) 6|a|² + 11(a·b) - 35|b|².', '4 × 1M = 4M', 'Aerospace navigation combines wind-velocity vectors and cross-product torque levers to compute glider drift and wing moment stability in 3D space.', '(i) (1/√14, 2/√14, 3/√14). (ii) cos θ = √6/(2√3) = 1/√2 => 45°. (iii) 3î + 2ĵ + k̂. (iv) 6|a|² + 11(a·b) - 35|b|².', 'HARD', true),
        ('12041111-0000-4000-8000-000000000079', 'If a line makes angles 90°, 135°, 45° with X, Y, Z axes respectively, its direction cosines are:', '{"A":"0, 1/√2, 1/√2","B":"0, -1/√2, 1/√2","C":"1, -1/√2, 1/√2","D":"0, -1/2, 1/2"}'::jsonb, 'B', 'MCQ', 'Mathematics', 'Three Dimensional Geometry', 1, 'cos 90°=0, cos 135°=-1/√2, cos 45°=1/√2.', NULL, NULL, 'cos 90°=0, cos 135°=-1/√2, cos 45°=1/√2.', 'EASY', true),
        ('12041111-0000-4000-8000-00000000007a', 'Relation satisfied by direction cosines l, m, n of any line in space is:', '{"A":"l + m + n = 1","B":"l² + m² + n² = 1","C":"l² + m² + n² = 0","D":"lmn = 1"}'::jsonb, 'B', 'MCQ', 'Mathematics', 'Three Dimensional Geometry', 1, 'l² + m² + n² = 1 always.', NULL, NULL, 'l² + m² + n² = 1 always.', 'EASY', true),
        ('12041111-0000-4000-8000-00000000007b', 'Cartesian equation of a line passing through (5, -4, 6) parallel to vector 3î + 7ĵ + 2k̂ is:', '{"A":"(x-5)/3 = (y+4)/7 = (z-6)/2","B":"(x+5)/3 = (y-4)/7 = (z+6)/2","C":"(x-3)/5 = (y-7)/(-4) = (z-2)/6","D":"x/3 = y/7 = z/2"}'::jsonb, 'A', 'MCQ', 'Mathematics', 'Three Dimensional Geometry', 1, '(x - x₁)/a = (y - y₁)/b = (z - z₁)/c.', NULL, NULL, '(x - x₁)/a = (y - y₁)/b = (z - z₁)/c.', 'EASY', true),
        ('12041111-0000-4000-8000-00000000007c', 'Two lines r = a₁ + λb₁ and r = a₂ + μb₂ are perpendicular if:', '{"A":"b₁ × b₂ = 0","B":"b₁ · b₂ = 0","C":"a₁ · a₂ = 0","D":"b₁ = b₂"}'::jsonb, 'B', 'MCQ', 'Mathematics', 'Three Dimensional Geometry', 1, 'Angle between direction vectors is 90°.', NULL, NULL, 'Angle between direction vectors is 90°.', 'EASY', true),
        ('12041111-0000-4000-8000-00000000007d', 'Shortest distance formula between two skew lines r = a₁ + λb₁ and r = a₂ + μb₂ is:', '{"A":"|(a₂ - a₁)·(b₁ × b₂)| / |b₁ × b₂|","B":"|(a₂ - a₁)×(b₁ · b₂)|","C":"|(b₁ × b₂)| / |a₂ - a₁|","D":"|a₂ - a₁|"}'::jsonb, 'A', 'MCQ', 'Mathematics', 'Three Dimensional Geometry', 1, 'Scalar projection of (a₂ - a₁) onto common normal (b₁ × b₂).', NULL, NULL, 'Scalar projection of (a₂ - a₁) onto common normal (b₁ × b₂).', 'EASY', true),
        ('12041111-0000-4000-8000-00000000007e', 'Assertion (A): If a line is equally inclined to the three coordinate axes X, Y, Z, its direction cosines are (±1/√3, ±1/√3, ±1/√3).
Reason (R): Equal angles α = β = γ give 3 cos²α = 1 => cos α = ±1/√3.
Choose the correct option:
A) Both A and R are true, and R is the correct explanation of A.
B) Both A and R are true, and R is not the correct explanation of A.
C) A is true but R is false.
D) A is false but R is true.', '{"A":"Both A and R are true, and R is the correct explanation of A","B":"Both A and R are true, and R is not the correct explanation of A","C":"A is true but R is false","D":"A is false but R is true"}'::jsonb, 'A', 'ASSERTION_REASON', 'Mathematics', 'Three Dimensional Geometry', 1, 'Cube main diagonals have direction cosines ±1/√3.', NULL, NULL, 'Cube main diagonals have direction cosines ±1/√3.', 'EASY', true),
        ('12041111-0000-4000-8000-00000000007f', 'Find value of p so lines (1-x)/3 = (7y-14)/(2p) = (z-3)/2 and (7-7x)/(3p) = (y-5)/1 = (6-z)/5 are at right angles.', NULL, NULL, 'VSA', 'Mathematics', 'Three Dimensional Geometry', 2, 'Standard DRs: (-3, 2p/7, 2) and (-3p/7, 1, -5). Dot product = 9p/7 + 2p/7 - 10 = 0 => 11p/7 = 10 => p = 70/11.', 'Standard DRs (1M) + p=70/11 (1M)', NULL, 'Standard DRs: (-3, 2p/7, 2) and (-3p/7, 1, -5). Dot product = 9p/7 + 2p/7 - 10 = 0 => 11p/7 = 10 => p = 70/11.', 'MEDIUM', true),
        ('12041111-0000-4000-8000-000000000080', 'Find distance between parallel lines r = (î+2ĵ-4k̂) + λ(2î+3ĵ+6k̂) and r = (3î+3ĵ-5k̂) + μ(2î+3ĵ+6k̂).', NULL, NULL, 'VSA', 'Mathematics', 'Three Dimensional Geometry', 2, 'd = |b × (a₂ - a₁)| / |b| = |(2î+3ĵ+6k̂) × (2î+ĵ-k̂)| / 7 = √((-9)²+(14)²+(-4)²)/7 = √293 / 7.', '2M', NULL, 'd = |b × (a₂ - a₁)| / |b| = |(2î+3ĵ+6k̂) × (2î+ĵ-k̂)| / 7 = √((-9)²+(14)²+(-4)²)/7 = √293 / 7.', 'MEDIUM', true),
        ('12041111-0000-4000-8000-000000000081', 'Find the vector and Cartesian equations of the line through (1, 2, -4) and perpendicular to lines (x-8)/3 = (y+19)/(-16) = (z-10)/7 and (x-15)/3 = (y-29)/8 = (z-5)/(-5).', NULL, NULL, 'SA', 'Mathematics', 'Three Dimensional Geometry', 3, 'b₁×b₂ = 24î + 36ĵ + 72k̂ = 12(2î + 3ĵ + 6k̂). Line: r = (î+2ĵ-4k̂) + λ(2î+3ĵ+6k̂); (x-1)/2 = (y-2)/3 = (z+4)/6.', 'Cross product (1.5M) + Equations (1.5M)', NULL, 'b₁×b₂ = 24î + 36ĵ + 72k̂ = 12(2î + 3ĵ + 6k̂). Line: r = (î+2ĵ-4k̂) + λ(2î+3ĵ+6k̂); (x-1)/2 = (y-2)/3 = (z+4)/6.', 'MEDIUM', true),
        ('12041111-0000-4000-8000-000000000082', 'Find coordinates of the foot of perpendicular drawn from point A(1, 8, 4) to the line joining B(0, -1, 3) and C(2, -3, -1).', NULL, NULL, 'SA', 'Mathematics', 'Three Dimensional Geometry', 3, 'Line BC: (2λ, -1-2λ, 3-4λ). AP ⊥ BC => 2(2λ-1) - 2(-2λ-9) - 4(-4λ-1) = 0 => 24λ + 20 = 0 => λ = -5/6 -> Foot (-5/3, 2/3, 19/3).', 'λ=-5/6 (1.5M) + Foot (1.5M)', NULL, 'Line BC: (2λ, -1-2λ, 3-4λ). AP ⊥ BC => 2(2λ-1) - 2(-2λ-9) - 4(-4λ-1) = 0 => 24λ + 20 = 0 => λ = -5/6 -> Foot (-5/3, 2/3, 19/3).', 'MEDIUM', true),
        ('12041111-0000-4000-8000-000000000083', 'Find the shortest distance between the lines:
r = (î + 2ĵ + k̂) + λ(î - ĵ + k̂) and r = (2î - ĵ - k̂) + μ(2î + ĵ + 2k̂).
Also check whether lines (x-1)/2 = (y-2)/3 = (z-3)/4 and (x-2)/3 = (y-4)/4 = (z-5)/5 intersect or are skew.', NULL, NULL, 'LA', 'Mathematics', 'Three Dimensional Geometry', 5, 'Part 1: a₂-a₁ = î-3ĵ-2k̂; b₁×b₂ = -3î + 0ĵ + 3k̂ (mag 3√2). |(1)(-3)+(-3)(0)+(-2)(3)| / (3√2) = 9/(3√2) = 3/√2 units (3M). Part 2: (a₂-a₁)·(b₁×b₂) = 0 => intersecting lines (2M).', 'Shortest distance 3/√2 (3M) + Intersection check (2M)', NULL, 'Part 1: a₂-a₁ = î-3ĵ-2k̂; b₁×b₂ = -3î + 0ĵ + 3k̂ (mag 3√2). |(1)(-3)+(-3)(0)+(-2)(3)| / (3√2) = 9/(3√2) = 3/√2 units (3M). Part 2: (a₂-a₁)·(b₁×b₂) = 0 => intersecting lines (2M).', 'HARD', true),
        ('12041111-0000-4000-8000-000000000084', '(i) Direction ratios of line joining A(2, 3, -4) and B(1, -2, 3). (ii) Angle between lines x/2 = y/2 = z/1 and (x-5)/4 = (y-2)/1 = (z-3)/8. (iii) Check if lines r = a₁ + λb and r = a₂ + μb are parallel or skew. (iv) Vector equation of line through origin parallel to y-axis.', NULL, NULL, 'CASE', 'Mathematics', 'Three Dimensional Geometry', 4, '(i) (-1, -5, 7). (ii) cos θ = (8+2+8)/(3×9) = 18/27 = 2/3 => θ = cos⁻¹(2/3). (iii) Parallel (same direction vector b). (iv) r = λĵ.', '4 × 1M = 4M', 'Air-traffic control towers verify whether two straight 3D flight corridors stay safely separated above minimum skew distance before clearing departures.', '(i) (-1, -5, 7). (ii) cos θ = (8+2+8)/(3×9) = 18/27 = 2/3 => θ = cos⁻¹(2/3). (iii) Parallel (same direction vector b). (iv) r = λĵ.', 'HARD', true),
        ('12041111-0000-4000-8000-000000000085', 'In a Linear Programming Problem (LPP), the linear function Z = ax + by to be maximised or minimised is called:', '{"A":"Constraint","B":"Objective function","C":"Feasible region","D":"Corner point"}'::jsonb, 'B', 'MCQ', 'Mathematics', 'Linear Programming', 1, 'Z = ax + by is the objective function.', NULL, NULL, 'Z = ax + by is the objective function.', 'EASY', true),
        ('12041111-0000-4000-8000-000000000086', 'According to the Corner Point Theorem, optimal (maximum/minimum) value of Z over a bounded feasible region always occurs at:', '{"A":"Origin only","B":"A corner point (vertex) of the feasible polygon","C":"Interior centroid","D":"Outside feasible set"}'::jsonb, 'B', 'MCQ', 'Mathematics', 'Linear Programming', 1, 'Extreme values occur at vertices of the convex feasible region.', NULL, NULL, 'Extreme values occur at vertices of the convex feasible region.', 'EASY', true),
        ('12041111-0000-4000-8000-000000000087', 'The region common to all constraints including non-negativity x ≥ 0, y ≥ 0 is called:', '{"A":"Optimal solution","B":"Feasible region","C":"Infeasible region","D":"Unbounded zone"}'::jsonb, 'B', 'MCQ', 'Mathematics', 'Linear Programming', 1, 'Set of points satisfying all linear inequalities simultaneously.', NULL, NULL, 'Set of points satisfying all linear inequalities simultaneously.', 'EASY', true),
        ('12041111-0000-4000-8000-000000000088', 'Maximum value of Z = 3x + 4y subject to x + y ≤ 4, x ≥ 0, y ≥ 0 is:', '{"A":"12","B":"16 (at (0, 4))","C":"0","D":"20"}'::jsonb, 'B', 'MCQ', 'Mathematics', 'Linear Programming', 1, 'Vertices (0,0)->0, (4,0)->12, (0,4)->16.', NULL, NULL, 'Vertices (0,0)->0, (4,0)->12, (0,4)->16.', 'EASY', true),
        ('12041111-0000-4000-8000-000000000089', 'When a feasible region is UNBOUNDED, minimum value M found at a corner point is valid ONLY if:', '{"A":"Open half-plane ax + by < M has NO point in common with the feasible region","B":"M is negative","C":"Origin is inside","D":"Constraints have ≤"}'::jsonb, 'A', 'MCQ', 'Mathematics', 'Linear Programming', 1, 'Verify open half-plane ax+by < M has empty overlap with unbounded feasible set.', NULL, NULL, 'Verify open half-plane ax+by < M has empty overlap with unbounded feasible set.', 'EASY', true),
        ('12041111-0000-4000-8000-00000000008a', 'Assertion (A): If the optimal value of Z occurs at two adjacent corner points P and Q of the feasible region, then Z attains that same optimal value at EVERY point on the segment PQ.
Reason (R): Since Z is linear, for any convex combination tP + (1-t)Q along the segment, Z(tP + (1-t)Q) = tM + (1-t)M = M.
Choose the correct option:
A) Both A and R are true, and R is the correct explanation of A.
B) Both A and R are true, and R is not the correct explanation of A.
C) A is true but R is false.
D) A is false but R is true.', '{"A":"Both A and R are true, and R is the correct explanation of A","B":"Both A and R are true, and R is not the correct explanation of A","C":"A is true but R is false","D":"A is false but R is true"}'::jsonb, 'A', 'ASSERTION_REASON', 'Mathematics', 'Linear Programming', 1, 'Infinitely many optimal solutions lie along boundary edge PQ.', NULL, NULL, 'Infinitely many optimal solutions lie along boundary edge PQ.', 'EASY', true),
        ('12041111-0000-4000-8000-00000000008b', 'Maximise Z = 3x + 2y subject to x + 2y ≤ 10, 3x + y ≤ 15, x ≥ 0, y ≥ 0.', NULL, NULL, 'VSA', 'Mathematics', 'Linear Programming', 2, 'Vertices: (0,0)->0, (5,0)->15, (4,3)->18, (0,5)->10. Maximum Z = 18 at (4, 3).', 'Vertices (1M) + Max 18 at (4,3) (1M)', NULL, 'Vertices: (0,0)->0, (5,0)->15, (4,3)->18, (0,5)->10. Maximum Z = 18 at (4, 3).', 'MEDIUM', true),
        ('12041111-0000-4000-8000-00000000008c', 'Minimise Z = 200x + 500y subject to x + 2y ≥ 10, 3x + 4y ≤ 24, x ≥ 0, y ≥ 0.', NULL, NULL, 'VSA', 'Mathematics', 'Linear Programming', 2, 'Vertices: (0,5)->2500, (4,3)->2300, (0,6)->3000. Minimum Z = 2300 at (4, 3).', '2M', NULL, 'Vertices: (0,5)->2500, (4,3)->2300, (0,6)->3000. Minimum Z = 2300 at (4, 3).', 'MEDIUM', true),
        ('12041111-0000-4000-8000-00000000008d', 'Solve graphically: Minimise and Maximise Z = 5x + 10y subject to x + 2y ≤ 120, x + y ≥ 60, x - 2y ≥ 0, x ≥ 0, y ≥ 0.', NULL, NULL, 'SA', 'Mathematics', 'Linear Programming', 3, 'Vertices: (60,0)->300, (120,0)->600, (60,30)->600, (40,20)->400. Minimum = 300 at (60, 0); Maximum = 600 at EVERY point on segment joining (120,0) and (60,30).', 'Vertices (1.5M) + Min 300 & Infinite Max 600 (1.5M)', NULL, 'Vertices: (60,0)->300, (120,0)->600, (60,30)->600, (40,20)->400. Minimum = 300 at (60, 0); Maximum = 600 at EVERY point on segment joining (120,0) and (60,30).', 'MEDIUM', true),
        ('12041111-0000-4000-8000-00000000008e', 'Solve graphically: Minimise Z = -50x + 20y subject to 2x - y ≥ -5, 3x + y ≥ 3, 2x - 3y ≤ 12, x ≥ 0, y ≥ 0 (Unbounded check!).', NULL, NULL, 'SA', 'Mathematics', 'Linear Programming', 3, 'Unbounded feasible region vertices (0,5)->100, (0,3)->60, (1,0)->-50, (6,0)->-300. Open half-plane -50x + 20y < -300 HAS points inside unbounded region -> NO minimum value exists!', 'Unbounded plot (1.5M) + Half-plane check showing no minimum (1.5M)', NULL, 'Unbounded feasible region vertices (0,5)->100, (0,3)->60, (1,0)->-50, (6,0)->-300. Open half-plane -50x + 20y < -300 HAS points inside unbounded region -> NO minimum value exists!', 'MEDIUM', true),
        ('12041111-0000-4000-8000-00000000008f', 'Solve graphically: Minimise and Maximise Z = x + 2y subject to x + 2y ≥ 100, 2x - y ≤ 0, 2x + y ≤ 200, x ≥ 0, y ≥ 0. Clearly list all constraints, intercept tables, corner points, and Z values.', NULL, NULL, 'LA', 'Mathematics', 'Linear Programming', 5, 'Bounded quadrilateral with vertices (0,50)->100, (20,40)->100, (50,100)->250, (0,200)->400. Minimum = 100 at all points on segment joining (0,50) and (20,40); Maximum = 400 at (0, 200).', 'Graph/tables & vertices (3M) + Min 100 & Max 400 (2M)', NULL, 'Bounded quadrilateral with vertices (0,50)->100, (20,40)->100, (50,100)->250, (0,200)->400. Minimum = 100 at all points on segment joining (0,50) and (20,40); Maximum = 400 at (0, 200).', 'HARD', true),
        ('12041111-0000-4000-8000-000000000090', '(i) Objective function for profit ₹40/table (x) and ₹25/chair (y). (ii) Budget/time constraints if table takes 3h, chair 2h out of max 60h and max 24 total pieces. (iii) Find corner points of feasible region. (iv) Optimal production plan maximising profit.', NULL, NULL, 'CASE', 'Mathematics', 'Linear Programming', 4, '(i) Max Z = 40x + 25y. (ii) 3x + 2y ≤ 60, x + y ≤ 24, x ≥ 0, y ≥ 0. (iii) (0,0), (20,0), (12,12), (0,24). (iv) Z(20,0)=800, Z(12,12)=480+300=780, Z(0,24)=600 -> Max ₹800 at 20 tables, 0 chairs.', '4 × 1M = 4M', 'A furniture workshop allocates limited carpentry hours and storage slots across tables and chairs to maximise weekly profit using corner-point linear programming.', '(i) Max Z = 40x + 25y. (ii) 3x + 2y ≤ 60, x + y ≤ 24, x ≥ 0, y ≥ 0. (iii) (0,0), (20,0), (12,12), (0,24). (iv) Z(20,0)=800, Z(12,12)=480+300=780, Z(0,24)=600 -> Max ₹800 at 20 tables, 0 chairs.', 'HARD', true),
        ('12041111-0000-4000-8000-000000000091', 'If P(A) = 0.8, P(B) = 0.5, and P(B | A) = 0.4, then P(A ∩ B) equals:', '{"A":"0.32","B":"0.20","C":"0.50","D":"0.40"}'::jsonb, 'A', 'MCQ', 'Mathematics', 'Probability', 1, 'P(A∩B) = P(A) × P(B|A) = 0.8 × 0.4 = 0.32.', NULL, NULL, 'P(A∩B) = P(A) × P(B|A) = 0.8 × 0.4 = 0.32.', 'EASY', true),
        ('12041111-0000-4000-8000-000000000092', 'If A and B are independent events with P(A) = 0.3 and P(B) = 0.4, then P(A ∪ B) is:', '{"A":"0.70","B":"0.58","C":"0.12","D":"0.88"}'::jsonb, 'B', 'MCQ', 'Mathematics', 'Probability', 1, '0.3 + 0.4 - 0.12 = 0.58.', NULL, NULL, '0.3 + 0.4 - 0.12 = 0.58.', 'EASY', true),
        ('12041111-0000-4000-8000-000000000093', 'A die is thrown twice and sum is observed to be 6. Conditional probability that number 4 appeared at least once is:', '{"A":"1/5","B":"2/5 (outcomes (2,4),(4,2) out of 5 sums)","C":"1/6","D":"3/5"}'::jsonb, 'B', 'MCQ', 'Mathematics', 'Probability', 1, 'Sum 6: {(1,5),(2,4),(3,3),(4,2),(5,1)} -> 2/5.', NULL, NULL, 'Sum 6: {(1,5),(2,4),(3,3),(4,2),(5,1)} -> 2/5.', 'EASY', true),
        ('12041111-0000-4000-8000-000000000094', 'Mean E(X) of a discrete random variable X taking values x_i with probabilities p_i is:', '{"A":"Σ x_i² p_i","B":"Σ x_i p_i","C":"Σ p_i","D":"(Σ x_i p_i)²"}'::jsonb, 'B', 'MCQ', 'Mathematics', 'Probability', 1, 'E(X) = μ = Σ x_i p_i.', NULL, NULL, 'E(X) = μ = Σ x_i p_i.', 'EASY', true),
        ('12041111-0000-4000-8000-000000000095', 'If A and B are independent events, which pair is ALSO guaranteed to be independent?', '{"A":"Only A and B","B":"A'' and B'' (as well as A & B'', A'' & B)","C":"None","D":"Only mutually exclusive"}'::jsonb, 'B', 'MCQ', 'Mathematics', 'Probability', 1, 'P(A''∩B'') = (1-P(A))(1-P(B)) = P(A'')P(B'').', NULL, NULL, 'P(A''∩B'') = (1-P(A))(1-P(B)) = P(A'')P(B'').', 'EASY', true),
        ('12041111-0000-4000-8000-000000000096', 'Assertion (A): If A and B are two non-zero probability mutually exclusive events, they CANNOT be independent.
Reason (R): For mutually exclusive events P(A ∩ B) = 0, whereas independent events require P(A ∩ B) = P(A)·P(B) > 0.
Choose the correct option:
A) Both A and R are true, and R is the correct explanation of A.
B) Both A and R are true, and R is not the correct explanation of A.
C) A is true but R is false.
D) A is false but R is true.', '{"A":"Both A and R are true, and R is the correct explanation of A","B":"Both A and R are true, and R is not the correct explanation of A","C":"A is true but R is false","D":"A is false but R is true"}'::jsonb, 'A', 'ASSERTION_REASON', 'Mathematics', 'Probability', 1, '0 ≠ P(A)P(B) when P(A), P(B) > 0.', NULL, NULL, '0 ≠ P(A)P(B) when P(A), P(B) > 0.', 'EASY', true),
        ('12041111-0000-4000-8000-000000000097', 'A couple has two children. Find probability that both are boys, if it is known that (i) at least one is a boy, (ii) elder child is a boy.', NULL, NULL, 'VSA', 'Mathematics', 'Probability', 2, 'Sample {BB, BG, GB, GG}. (i) 1/3; (ii) {BB, BG} -> 1/2.', '1M each', NULL, 'Sample {BB, BG, GB, GG}. (i) 1/3; (ii) {BB, BG} -> 1/2.', 'MEDIUM', true),
        ('12041111-0000-4000-8000-000000000098', 'Probability of solving specific problem independently by A and B are 1/2 and 1/3 respectively. Find probability that the problem is solved.', NULL, NULL, 'VSA', 'Mathematics', 'Probability', 2, '1 - P(A'')P(B'') = 1 - (1/2)(2/3) = 1 - 1/3 = 2/3.', '1M + 1M', NULL, '1 - P(A'')P(B'') = 1 - (1/2)(2/3) = 1 - 1/3 = 2/3.', 'MEDIUM', true),
        ('12041111-0000-4000-8000-000000000099', 'Bag I has 3 red and 4 black balls; Bag II has 5 red and 6 black balls. One ball is drawn at random from one of the bags and found to be red. Find probability it was drawn from Bag II (Bayes'' Theorem).', NULL, NULL, 'SA', 'Mathematics', 'Probability', 3, 'P(E₁)=P(E₂)=½. P(R|E₁)=3/7, P(R|E₂)=5/11. P(E₂|R) = (½ × 5/11) / [½(3/7 + 5/11)] = (35/77) / (68/77) = 35 / 68.', 'Prior & Likelihoods (1.5M) + Bayes 35/68 (1.5M)', NULL, 'P(E₁)=P(E₂)=½. P(R|E₁)=3/7, P(R|E₂)=5/11. P(E₂|R) = (½ × 5/11) / [½(3/7 + 5/11)] = (35/77) / (68/77) = 35 / 68.', 'MEDIUM', true),
        ('12041111-0000-4000-8000-00000000009a', 'Two cards are drawn successively WITH replacement from a well-shuffled pack of 52 cards. Find the probability distribution and Mean of the number of aces.', NULL, NULL, 'SA', 'Mathematics', 'Probability', 3, 'X ∈ {0, 1, 2}, p=1/13, q=12/13. P(0)=144/169, P(1)=24/169, P(2)=1/169. Mean E(X) = 24/169 + 2/169 = 26/169 = 2/13.', 'Distribution (2M) + Mean 2/13 (1M)', NULL, 'X ∈ {0, 1, 2}, p=1/13, q=12/13. P(0)=144/169, P(1)=24/169, P(2)=1/169. Mean E(X) = 24/169 + 2/169 = 26/169 = 2/13.', 'MEDIUM', true),
        ('12041111-0000-4000-8000-00000000009b', 'In answering a question on a multiple choice test, a student either knows the answer or guesses. Let 3/4 be the probability that he knows the answer and 1/4 that he guesses. Assuming a student who guesses gives the correct answer with probability 1/4, what is the probability that the student knew the answer given that he answered it correctly? Also find the probability distribution of number of heads in 3 tosses of a biased/fair coin (take fair coin -> Mean & Variance).', NULL, NULL, 'LA', 'Mathematics', 'Probability', 5, 'Part 1 Bayes: P(K)=3/4, P(G)=1/4, P(C|K)=1, P(C|G)=1/4 -> P(K|C) = (3/4×1)/(3/4 + 1/16) = 12/13 (3M). Part 2: X={0,1,2,3} probs {1/8, 3/8, 3/8, 1/8}, Mean = 1.5, Var = E(X²)-[E(X)]² = 3 - 2.25 = 0.75 (2M).', 'Bayes 12/13 (3M) + Dist/Mean/Var (2M)', NULL, 'Part 1 Bayes: P(K)=3/4, P(G)=1/4, P(C|K)=1, P(C|G)=1/4 -> P(K|C) = (3/4×1)/(3/4 + 1/16) = 12/13 (3M). Part 2: X={0,1,2,3} probs {1/8, 3/8, 3/8, 1/8}, Mean = 1.5, Var = E(X²)-[E(X)]² = 3 - 2.25 = 0.75 (2M).', 'HARD', true),
        ('12041111-0000-4000-8000-00000000009c', '(i) Bayes formula statement for P(E_i | A). (ii) Three factories A, B, C produce 25%, 35%, 40% of bolts with defect rates 5%, 4%, 2%; find overall defective bolt probability P(D). (iii) Probability a randomly chosen defective bolt came from Factory B. (iv) If P(A)=3/5 and P(B)=1/5 independent, find P(A ∩ B).', NULL, NULL, 'CASE', 'Mathematics', 'Probability', 4, '(i) P(E_i)P(A|E_i) / Σ P(E_j)P(A|E_j). (ii) 0.25(0.05) + 0.35(0.04) + 0.40(0.02) = 0.0125 + 0.0140 + 0.0080 = 0.0345. (iii) 0.0140 / 0.0345 = 28 / 69. (iv) 3/25.', '4 × 1M = 4M', 'Medical diagnostic labs apply Bayes'' Theorem across false-positive and true-positive screening rates to compute true disease probability after a positive test result.', '(i) P(E_i)P(A|E_i) / Σ P(E_j)P(A|E_j). (ii) 0.25(0.05) + 0.35(0.04) + 0.40(0.02) = 0.0125 + 0.0140 + 0.0080 = 0.0345. (iii) 0.0140 / 0.0345 = 28 / 69. (iv) 3/25.', 'HARD', true),
        ('12041111-0000-4000-8000-00000000009d', 'Let A = {1, 2, 3}. How many equivalence relations containing (1, 2) can be defined on set A?', '{"A":"1","B":"2","C":"3","D":"4"}'::jsonb, 'B', 'MCQ', 'Mathematics', 'Relations & Functions', 1, 'Option (B) is correct. Smallest equivalence relation containing (1, 2) is {(1,1), (2,2), (3,3), (1,2), (2,1)}. The only larger equivalence relation containing (1, 2) is the universal relation A × A -> 2 equivalence relations.', 'Minimal equivalence + Universal relation A×A -> 2 [1 Mark]', NULL, 'Examiner Tip: NCERT Exemplar / CBSE Board favourite MCQ: remember answer is 2. | Common Pitfall: Thinking {(1,2), (2,1)} alone is reflexive without (3,3).', 'EASY', true),
        ('12041111-0000-4000-8000-00000000009e', 'The principal value of cos⁻¹(cos(7π/6)) is:', '{"A":"7π/6","B":"5π/6","C":"π/6","D":"-π/6"}'::jsonb, 'B', 'MCQ', 'Mathematics', 'Inverse Trigonometry', 1, 'Option (B) is correct. Principal range of cos⁻¹ is [0, π]. Since 7π/6 ∉ [0, π], write cos(7π/6) = cos(2π - 5π/6) = cos(5π/6), and 5π/6 ∈ [0, π].', 'Map 7π/6 into [0, π] via 2π - 5π/6 -> 5π/6 [1 Mark]', NULL, 'Examiner Tip: Principal ranges: sin⁻¹ [-π/2, π/2]; cos⁻¹ [0, π]; tan⁻¹ (-π/2, π/2). | Common Pitfall: Cancelling cos⁻¹(cos θ) = θ directly when θ > π.', 'EASY', true),
        ('12041111-0000-4000-8000-00000000009f', 'If A is a square matrix of order 3 such that |A| = 5, then the value of |adj A| and |3A| are respectively:', '{"A":"25 and 15","B":"25 and 135","C":"125 and 45","D":"5 and 135"}'::jsonb, 'B', 'MCQ', 'Mathematics', 'Matrices & Determinants', 1, 'Option (B) is correct. For order n = 3: |adj A| = |A|^(n-1) = 5² = 25; |kA| = kⁿ|A| = 3³ × 5 = 27 × 5 = 135.', '|adj A| = |A|² = 25; |3A| = 3³|A| = 135 [1 Mark]', NULL, 'Examiner Tip: Watch out for both identities: |adj A| = |A|^(n-1) and |kA| = kⁿ|A|. | Common Pitfall: Computing |3A| = 3|A| = 15.', 'EASY', true),
        ('12041111-0000-4000-8000-0000000000a0', 'If A is a 3 × 3 skew-symmetric matrix, then the sum of its principal diagonal elements (Trace) and |A| are respectively:', '{"A":"1 and 1","B":"0 and 0","C":"3 and 0","D":"0 and 1"}'::jsonb, 'B', 'MCQ', 'Mathematics', 'Matrices', 1, 'Option (B) is correct. All diagonal entries of a skew-symmetric matrix satisfy a_ii = -a_ii => a_ii = 0 (Trace = 0). Also |A| = |A''| = |-A| = (-1)³|A| = -|A| => |A| = 0 for odd order!', 'Diagonal entries 0 -> Trace = 0; odd-order skew-symmetric |A| = 0 [1 Mark]', NULL, 'Examiner Tip: Determinant of ANY odd-order skew-symmetric matrix is ALWAYS 0! | Common Pitfall: Assuming even-order skew-symmetric matrices also have |A| = 0.', 'EASY', true),
        ('12041111-0000-4000-8000-0000000000a1', 'If x = at² and y = 2at, then d²y/dx² at t = 1 is:', '{"A":"1/t","B":"-1/(2a)","C":"-1/(2at³)","D":"1/(2a)"}'::jsonb, 'B', 'MCQ', 'Mathematics', 'Continuity & Differentiability', 1, 'Option (B) is correct. dy/dx = (2a)/(2at) = 1/t. Differentiating again w.r.t. x: d²y/dx² = d/dt(1/t) · (dt/dx) = (-1/t²) · (1/(2at)) = -1/(2at³). At t = 1, value = -1/(2a).', 'dy/dx = 1/t -> d²y/dx² = (-1/t²)(dt/dx) = -1/(2a) [1 Mark]', NULL, 'Examiner Tip: NEVER forget to multiply by (dt/dx) when computing d²y/dx² parametrically! | Common Pitfall: Stopping at d/dt(1/t) = -1/t² = -1 without dividing by dx/dt.', 'EASY', true),
        ('12041111-0000-4000-8000-0000000000a2', 'The function f(x) = x² - 4x + 6 is strictly increasing in the interval:', '{"A":"(-∞, 2)","B":"(2, ∞)","C":"(-∞, ∞)","D":"(0, 2)"}'::jsonb, 'B', 'MCQ', 'Mathematics', 'Applications of Derivatives', 1, 'Option (B) is correct. f''(x) = 2x - 4 > 0 => x > 2 => strictly increasing on (2, ∞).', 'f''(x) = 2x - 4 > 0 -> (2, ∞) [1 Mark]', NULL, 'Examiner Tip: Strictly increasing requires f''(x) > 0 (open interval). | Common Pitfall: Choosing (-∞, 2) where f''(x) < 0.', 'EASY', true),
        ('12041111-0000-4000-8000-0000000000a3', 'Evaluate the definite integral ∫_{-π/2}^{π/2} (x³ + x cos x + tan⁵ x + 1) dx:', '{"A":"0","B":"π/2","C":"π","D":"2π"}'::jsonb, 'C', 'MCQ', 'Mathematics', 'Integrals', 1, 'Option (C) is correct. x³, x cos x, and tan⁵ x are ALL odd functions (f(-x) = -f(x)), so their integrals over [-π/2, π/2] vanish! Remaining integral = ∫_{-π/2}^{π/2} 1 dx = π/2 - (-π/2) = π.', 'Odd terms vanish -> ∫ 1 dx = π [1 Mark]', NULL, 'Examiner Tip: Check parity of EACH term separately instead of assuming the whole integrand is odd. | Common Pitfall: Missing the constant "+1" (which is EVEN) and marking 0!', 'EASY', true),
        ('12041111-0000-4000-8000-0000000000a4', '∫ e^x (sin x + cos x) dx is equal to:', '{"A":"e^x cos x + C","B":"e^x sin x + C","C":"-e^x sin x + C","D":"e^x (sin x - cos x) + C"}'::jsonb, 'B', 'MCQ', 'Mathematics', 'Integrals', 1, 'Option (B) is correct. Using ∫ e^x [f(x) + f''(x)] dx = e^x f(x) + C with f(x) = sin x and f''(x) = cos x -> e^x sin x + C.', 'Identify f(x) = sin x, f''(x) = cos x -> e^x sin x + C [1 Mark]', NULL, 'Examiner Tip: Verify by differentiating e^x sin x = e^x(sin x + cos x). | Common Pitfall: Choosing e^x cos x (whose derivative has -sin x).', 'EASY', true),
        ('12041111-0000-4000-8000-0000000000a5', 'The order and degree of the differential equation [ 1 + (dy/dx)² ]^(3/2) = k (d²y/dx²) are respectively:', '{"A":"2 and 3","B":"2 and 2","C":"1 and 3","D":"2 and not defined"}'::jsonb, 'B', 'MCQ', 'Mathematics', 'Differential Equations', 1, 'Option (B) is correct. Squaring both sides removes fractional exponent 3/2: [1 + (dy/dx)²]³ = k² (d²y/dx²)². Highest derivative is d²y/dx² (order = 2) with highest power = 2 (degree = 2).', 'Square both sides -> order 2, degree 2 [1 Mark]', NULL, 'Examiner Tip: Always clear fractional powers/radicals of derivatives before reading the degree! | Common Pitfall: Reading power 3 on (dy/dx)² instead of highest-order derivative d²y/dx².', 'EASY', true),
        ('12041111-0000-4000-8000-0000000000a6', 'Find the scalar projection of vector a = 2î + 3ĵ + 2k̂ on vector b = î + 2ĵ + k̂:', '{"A":"10 / √6","B":"10 / √17","C":"5 / √6","D":"√6"}'::jsonb, 'A', 'MCQ', 'Mathematics', 'Vectors', 1, 'Option (A) is correct. Projection of a on b = (a · b) / |b| = (2(1) + 3(2) + 2(1)) / √(1² + 2² + 1²) = (2 + 6 + 2) / √6 = 10 / √6.', '(a · b) / |b| = 10 / √6 [1 Mark]', NULL, 'Examiner Tip: Divide by magnitude of the vector ONTO WHICH we project (|b|)! | Common Pitfall: Dividing by |a| = √17 instead of |b| = √6.', 'EASY', true),
        ('12041111-0000-4000-8000-0000000000a7', 'If a line makes angles α, β, γ with the positive directions of x, y, and z axes respectively, then sin²α + sin²β + sin²γ equals:', '{"A":"1","B":"2","C":"3","D":"0"}'::jsonb, 'B', 'MCQ', 'Mathematics', '3D Geometry', 1, 'Option (B) is correct. Using cos²α + cos²β + cos²γ = 1: (1 - sin²α) + (1 - sin²β) + (1 - sin²γ) = 1 => 3 - (sin²α + sin²β + sin²γ) = 1 => sin²α + sin²β + sin²γ = 2.', 'Substitute cos²θ = 1 - sin²θ -> sum = 2 [1 Mark]', NULL, 'Examiner Tip: Sum of cos² = 1; Sum of sin² = 2; Sum of cos(2θ) = -1. | Common Pitfall: Writing 1 (forgetting it''s sin², not cos²).', 'EASY', true),
        ('12041111-0000-4000-8000-0000000000a8', 'In a Linear Programming Problem (LPP), the optimal value (maximum or minimum) of the objective function Z = ax + by over a bounded feasible region always occurs at:', '{"A":"Interior points of the feasible region","B":"Origin (0, 0) always","C":"One or more corner points (vertices) of the feasible region","D":"Midpoints of constraints"}'::jsonb, 'C', 'MCQ', 'Mathematics', 'Linear Programming', 1, 'Option (C) is correct. By the Fundamental Theorem of Linear Programming, if Z attains an optimal value on a bounded feasible polygon, it occurs at a corner point (vertex).', 'Identify corner points (vertices) [1 Mark]', NULL, 'Examiner Tip: If two adjacent vertices give the same optimal Z, every point on the line segment joining them is also optimal! | Common Pitfall: Testing interior points.', 'EASY', true),
        ('12041111-0000-4000-8000-0000000000a9', 'If A and B are independent events with P(A) = 0.3 and P(B) = 0.4, then P(A | B) and P(A ∪ B) are respectively:', '{"A":"0.12 and 0.70","B":"0.30 and 0.58","C":"0.40 and 0.58","D":"0.30 and 0.70"}'::jsonb, 'B', 'MCQ', 'Mathematics', 'Probability', 1, 'Option (B) is correct. For independent events, P(A | B) = P(A) = 0.30. Also P(A ∩ B) = 0.3 × 0.4 = 0.12 => P(A ∪ B) = 0.3 + 0.4 - 0.12 = 0.58.', 'P(A|B) = P(A) = 0.30; P(A∪B) = 0.58 [1 Mark]', NULL, 'Examiner Tip: Independent does NOT mean mutually exclusive (mutually exclusive have P(A∩B)=0)! | Common Pitfall: Adding 0.3 + 0.4 = 0.70 without subtracting 0.12.', 'EASY', true),
        ('12041111-0000-4000-8000-0000000000aa', 'Assertion (A): Every differentiable function is continuous, but every continuous function is not necessarily differentiable.
Reason (R): f(x) = |x| is continuous at x = 0 yet not differentiable at x = 0 (LHD = -1 ≠ RHD = +1).', '{"A":"Both A and R are true, and R is the correct explanation of A","B":"Both A and R are true, but R is not the correct explanation of A","C":"A is true, but R is false","D":"A is false, but R is true"}'::jsonb, 'A', 'ASSERTION_REASON', 'Mathematics', 'Continuity', 1, 'Option (A) is correct. Differentiability guarantees continuity, while |x| has a sharp corner at x = 0 (LHD = -1 ≠ RHD = +1), proving continuity alone does not guarantee differentiability.', 'Option (A) with |x| counterexample [1 Mark]', NULL, 'Examiner Tip: Corner points on continuous curves lack unique tangents -> non-differentiable. | Common Pitfall: Saying |x| is discontinuous at x = 0.', 'EASY', true),
        ('12041111-0000-4000-8000-0000000000ab', 'Assertion (A): If |a + b| = |a - b| for non-zero vectors a and b, then vectors a and b are perpendicular.
Reason (R): Squaring gives 4 (a · b) = 0 => a · b = 0.', '{"A":"Both A and R are true, and R is the correct explanation of A","B":"Both A and R are true, but R is not the correct explanation of A","C":"A is true, but R is false","D":"A is false, but R is true"}'::jsonb, 'A', 'ASSERTION_REASON', 'Mathematics', 'Vectors', 1, 'Option (A) is correct. |a + b|² = |a - b|² => 4(a·b) = 0 => a ⊥ b.', 'Option (A) proving a · b = 0 [1 Mark]', NULL, 'Examiner Tip: Use a · a = |a|² cleanly in vector magnitude proofs. | Common Pitfall: Confusing perpendicular condition (a·b = 0) with parallel condition (a×b = 0).', 'EASY', true),
        ('12041111-0000-4000-8000-0000000000ac', 'Express tan⁻¹[ cos x / (1 - sin x) ], where -3π/2 < x < π/2, in its simplest form.', NULL, NULL, 'VSA', 'Mathematics', 'Inverse Trigonometry', 2, 'Write cos x = sin(π/2 - x) and sin x = cos(π/2 - x) (or use half angles cos²(x/2)-sin²(x/2) over (cos x/2 - sin x/2)²):
[cos²(x/2) - sin²(x/2)] / [cos(x/2) - sin(x/2)]² = [cos(x/2) + sin(x/2)] / [cos(x/2) - sin(x/2)]
Divide top and bottom by cos(x/2):
= [1 + tan(x/2)] / [1 - tan(x/2)] = tan(π/4 + x/2).
Hence tan⁻¹(tan(π/4 + x/2)) = π/4 + x/2 (since -π/2 < π/4 + x/2 < π/2).', 'Half-angle factorisation to [1 + tan(x/2)]/[1 - tan(x/2)] [1 Mark] | Simplify to π/4 + x/2 within principal domain [1 Mark]', NULL, 'Examiner Tip: Replacing 1 = cos²(x/2) + sin²(x/2) converts 1 ± sin x directly into perfect squares! | Common Pitfall: Using cos(π/2 + x) improperly without verifying principal domain (-π/2, π/2).', 'MEDIUM', true),
        ('12041111-0000-4000-8000-0000000000ad', 'The volume of a cube is increasing at the rate of 8 cm³/s. How fast is the surface area increasing when the length of an edge is 12 cm?', NULL, NULL, 'VSA', 'Mathematics', 'Applications of Derivatives', 2, 'Let edge = x. V = x³ => dV/dt = 3x² (dx/dt) = 8 => dx/dt = 8 / (3x²).
Surface area S = 6x² => dS/dt = 12x (dx/dt) = 12x × [8 / (3x²)] = 32 / x.
At x = 12 cm: dS/dt = 32 / 12 = 8/3 cm²/s ≈ 2.67 cm²/s.', 'Differentiate V=x³ -> dx/dt = 8/(3x²) [1 Mark] | Compute dS/dt = 32/x = 8/3 cm²/s [1 Mark]', NULL, 'Examiner Tip: Substitute x = 12 ONLY AFTER differentiating! | Common Pitfall: Writing unit cm/s instead of cm²/s.', 'MEDIUM', true),
        ('12041111-0000-4000-8000-0000000000ae', 'Evaluate: ∫ [ 1 / (x - √x) ] dx.', NULL, NULL, 'VSA', 'Mathematics', 'Integrals', 2, 'Factor √x in denominator: ∫ [ 1 / (√x (√x - 1)) ] dx.
Substitute t = √x - 1 => dt = (1 / (2√x)) dx => dx / √x = 2 dt.
Integral = ∫ (2 / t) dt = 2 log |t| + C = 2 log |√x - 1| + C.', 'Factor √x & substitute t = √x - 1 [1 Mark] | Integrate -> 2 log|√x - 1| + C [1 Mark]', NULL, 'Examiner Tip: Always substitute back to original variable x and include +C! | Common Pitfall: Forgetting the factor of 2 from d(√x) = dx/(2√x).', 'MEDIUM', true),
        ('12041111-0000-4000-8000-0000000000af', 'Find a unit vector perpendicular to both vectors a = 3î + ĵ + 2k̂ and b = 2î - 2ĵ + 4k̂.', NULL, NULL, 'VSA', 'Mathematics', 'Vectors', 2, 'a × b = | î  ĵ  k̂ ; 3 1 2 ; 2 -2 4 | = î(4 + 4) - ĵ(12 - 4) + k̂(-6 - 2) = 8î - 8ĵ - 8k̂.
|a × b| = √(8² + (-8)² + (-8)²) = 8√3.
Unit vector n̂ = ± (a × b) / |a × b| = ± (1/√3)(î - ĵ - k̂).', 'Cross product a × b = 8î - 8ĵ - 8k̂ [1 Mark] | Divide by 8√3 -> ±(î - ĵ - k̂)/√3 [1 Mark]', NULL, 'Examiner Tip: Include ± when question asks "a unit vector perpendicular to both", since both +n̂ and -n̂ are valid. | Common Pitfall: Sign error on the ĵ cofactor in 3×3 determinant.', 'MEDIUM', true),
        ('12041111-0000-4000-8000-0000000000b0', 'Find the general solution of the differential equation: dy/dx = (1 + y²) / (1 + x²).', NULL, NULL, 'VSA', 'Mathematics', 'Differential Equations', 2, 'Separating variables:
dy / (1 + y²) = dx / (1 + x²).
Integrating both sides:
tan⁻¹ y = tan⁻¹ x + C (or tan⁻¹( (y - x)/(1 + xy) ) = C => y - x = k(1 + xy)).', 'Separate variables dy/(1+y²) = dx/(1+x²) [1 Mark] | Integrate -> tan⁻¹ y = tan⁻¹ x + C [1 Mark]', NULL, 'Examiner Tip: Verify constant C is added immediately upon integrating. | Common Pitfall: Leaving without integrating or omitting +C.', 'MEDIUM', true),
        ('12041111-0000-4000-8000-0000000000b1', 'Find the values of a and b such that the function f(x) defined below is continuous everywhere:
f(x) = 5 if x ≤ 2;  ax + b if 2 < x < 10;  21 if x ≥ 10.', NULL, NULL, 'SA', 'Mathematics', 'Continuity', 3, 'For continuity at x = 2: LHL = f(2) = 5 = RHL = lim(x→2⁺)(ax + b) = 2a + b => 2a + b = 5 ...(1)
For continuity at x = 10: LHL = lim(x→10⁻)(ax + b) = 10a + b = f(10) = 21 => 10a + b = 21 ...(2)
Subtracting (1) from (2): 8a = 16 => a = 2.
From (1): 2(2) + b = 5 => b = 1.
Hence a = 2, b = 1.', 'Continuity at x=2 -> 2a + b = 5 [1 Mark] | Continuity at x=10 -> 10a + b = 21 [1 Mark] | Solve simultaneously -> a = 2, b = 1 [1 Mark]', NULL, 'Examiner Tip: Write LHL = RHL = f(c) notation explicitly for full board marks. | Common Pitfall: Solving only one boundary point.', 'MEDIUM', true),
        ('12041111-0000-4000-8000-0000000000b2', 'Differentiate y = x^(sin x) + (sin x)^x with respect to x.', NULL, NULL, 'SA', 'Mathematics', 'Differentiation', 3, 'Let u = x^(sin x) and v = (sin x)^x => y = u + v => dy/dx = du/dx + dv/dx.
For u: ln u = sin x ln x => (1/u) du/dx = (sin x)/x + cos x ln x => du/dx = x^(sin x)[ (sin x)/x + cos x ln x ].
For v: ln v = x ln(sin x) => (1/v) dv/dx = ln(sin x) + x cot x => dv/dx = (sin x)^x[ ln(sin x) + x cot x ].
Hence dy/dx = x^(sin x)[(sin x)/x + cos x ln x] + (sin x)^x[ln(sin x) + x cot x].', 'Split y = u + v (DO NOT take log directly on sum!) [1 Mark] | Compute du/dx via logarithmic differentiation [1 Mark] | Compute dv/dx & combine [1 Mark]', NULL, 'Examiner Tip: CRITICAL: log(u + v) ≠ log u + log v! Always differentiate u and v separately! | Common Pitfall: Taking log(y) = log(x^sinx) + log((sinx)^x) directly!', 'MEDIUM', true),
        ('12041111-0000-4000-8000-0000000000b3', 'Evaluate: ∫₀^(π/2) [ √(sin x) / (√(sin x) + √(cos x)) ] dx.', NULL, NULL, 'SA', 'Mathematics', 'Integrals', 3, 'Let I = ∫₀^(π/2) [ √(sin x) / (√(sin x) + √(cos x)) ] dx ...(1)
Using P₄: ∫₀^a f(x)dx = ∫₀^a f(a - x)dx with a = π/2:
I = ∫₀^(π/2) [ √(cos x) / (√(cos x) + √(sin x)) ] dx ...(2)
Adding (1) and (2): 2I = ∫₀^(π/2) 1 dx = π/2 => I = π/4.', 'Apply King''s property f(π/2 - x) [1.5 Marks] | Add (1) + (2) -> 2I = π/2 -> I = π/4 [1.5 Marks]', NULL, 'Examiner Tip: State the property used explicitly (∫₀^a f(x)dx = ∫₀^a f(a-x)dx). | Common Pitfall: Forgetting the factor 2 in 2I = π/2 and writing π/2.', 'MEDIUM', true),
        ('12041111-0000-4000-8000-0000000000b4', 'Evaluate: ∫ [ x / ((x - 1)(x - 2)) ] dx.', NULL, NULL, 'SA', 'Mathematics', 'Integrals', 3, 'Using partial fractions: x / [(x - 1)(x - 2)] = A/(x - 1) + B/(x - 2) => x = A(x - 2) + B(x - 1).
Put x = 1: 1 = -A => A = -1.
Put x = 2: 2 = B => B = 2.
Integral = ∫ [ -1/(x - 1) + 2/(x - 2) ] dx = 2 log|x - 2| - log|x - 1| + C = log|(x - 2)² / (x - 1)| + C.', 'Partial fractions A = -1, B = 2 [1.5 Marks] | Integrate -> log|(x-2)²/(x-1)| + C [1.5 Marks]', NULL, 'Examiner Tip: Check A + B = 1 and -2A - B = 0 before integrating. | Common Pitfall: Sign mistake in A = -1.', 'MEDIUM', true),
        ('12041111-0000-4000-8000-0000000000b5', 'Solve the linear differential equation: (1 + x²) dy/dx + 2xy = 4x².', NULL, NULL, 'SA', 'Mathematics', 'Differential Equations', 3, 'Divide by (1 + x²): dy/dx + [2x / (1 + x²)] y = 4x² / (1 + x²).
Here P = 2x/(1 + x²), Q = 4x²/(1 + x²).
Integrating Factor IF = e^(∫ 2x/(1+x²) dx) = e^(ln(1+x²)) = 1 + x².
Solution: y · (1 + x²) = ∫ [4x² / (1 + x²)] (1 + x²) dx = ∫ 4x² dx = (4/3)x³ + C.
Hence y = [ (4/3)x³ + C ] / (1 + x²).', 'Standard form dy/dx + Py = Q [0.5 Mark] | Integrating Factor IF = 1 + x² [1 Mark] | Final solution y(1+x²) = 4x³/3 + C [1.5 Marks]', NULL, 'Examiner Tip: Always check whether leading dy/dx coefficient is 1 before writing P and Q! | Common Pitfall: Forgetting to divide Q (4x²) by (1 + x²) as well.', 'MEDIUM', true),
        ('12041111-0000-4000-8000-0000000000b6', 'Solve the following LPP graphically: Maximize Z = 4x + y subject to constraints x + y ≤ 50, 3x + y ≤ 90, x ≥ 0, y ≥ 0.', NULL, NULL, 'SA', 'Mathematics', 'Linear Programming', 3, 'Boundary lines:
• L₁: x + y = 50 passes through (50, 0) & (0, 50).
• L₂: 3x + y = 90 passes through (30, 0) & (0, 90).
Intersection of L₁ and L₂: Subtracting -> 2x = 40 => x = 20, y = 30.
Bounded feasible region corner points & Z = 4x + y:
• O(0, 0) -> Z = 0
• A(30, 0) -> Z = 120 (MAXIMUM)
• B(20, 30) -> Z = 80 + 30 = 110
• C(0, 50) -> Z = 50.
Maximum value of Z is 120 at (30, 0).', 'Intersection (20, 30) & 4 feasible vertices [1.5 Marks] | Evaluate Z at all corner points -> Max Z = 120 at (30, 0) [1.5 Marks]', NULL, 'Examiner Tip: Shade the feasible region clearly and show corner table. | Common Pitfall: Using wrong x-intercept (50, 0) instead of (30, 0) in feasible region.', 'MEDIUM', true),
        ('12041111-0000-4000-8000-0000000000b7', 'If A = [[2, -3, 5], [3, 2, -4], [1, 1, -2]], find A⁻¹. Using A⁻¹, solve the system of linear equations:
2x - 3y + 5z = 11
3x + 2y - 4z = -5
x + y - 2z = -3', NULL, NULL, 'LA', 'Mathematics', 'Matrices', 5, '|A| = 2(-4 + 4) - (-3)(-6 + 4) + 5(3 - 2) = 0 + 3(-2) + 5(1) = -6 + 5 = -1 ≠ 0 (non-singular, A⁻¹ exists).
Cofactors of A:
C₁₁=0, C₁₂=2, C₁₃=1
C₂₁=-1, C₂₂=-9, C₂₃=-5
C₃₁=2, C₃₂=23, C₃₃=13.
adj A = Transpose of cofactor matrix = [[0, -1, 2], [2, -9, 23], [1, -5, 13]].
A⁻¹ = (1/-1) adj A = [[0, 1, -2], [-2, 9, -23], [-1, 5, -13]].
Solution X = A⁻¹ B where B = [11, -5, -3]^T:
x = 0(11) + 1(-5) - 2(-3) = 1
y = -2(11) + 9(-5) - 23(-3) = -22 - 45 + 69 = 2
z = -1(11) + 5(-5) - 13(-3) = -11 - 25 + 39 = 3.
Hence x = 1, y = 2, z = 3.', '|A| = -1 ≠ 0 [1 Mark] | All 9 cofactors & adj A [2 Marks] | A⁻¹ and X = A⁻¹ B -> x=1, y=2, z=3 [2 Marks]', NULL, 'Examiner Tip: Plug (1, 2, 3) back into ALL 3 equations right away to verify 100% accuracy! | Common Pitfall: Forgetting to take Transpose of the cofactor matrix for adj A.', 'HARD', true),
        ('12041111-0000-4000-8000-0000000000b8', 'Using integration, find the area of the region in the first quadrant enclosed by the x-axis, the line y = x, and the circle x² + y² = 32.', NULL, NULL, 'LA', 'Mathematics', 'Applications of Integrals', 5, 'Intersection of y = x and x² + y² = 32: 2x² = 32 => x² = 16 => x = 4 (in first quadrant) -> point (4, 4).
Circle radius r = √32 = 4√2 -> meets x-axis at (4√2, 0).
Split area at x = 4:
A = ∫₀⁴ x dx + ∫₄^(4√2) √(32 - x²) dx
= [x²/2]₀⁴ + [ (x/2)√(32 - x²) + (32/2) sin⁻¹(x / (4√2)) ]₄^(4√2)
= 8 + [ (0 + 16 · π/2) - (2√16 + 16 sin⁻¹(1/√2)) ]
= 8 + [ 8π - (8 + 16 · π/4) ] = 8 + 8π - 8 - 4π = 4π sq. units.', 'Sketch figure & find intersection (4, 4) and (4√2, 0) [1.5 Marks] | Split integral ∫₀⁴ x dx + ∫₄^(4√2) √(32-x²) dx [1.5 Marks] | Evaluate standard √(a²-x²) integral -> 4π sq. units [2 Marks]', NULL, 'Examiner Tip: Quick geometric sanity check: θ = 45° (1/8 of full circle area πr² = 32π) => 32π / 8 = 4π! | Common Pitfall: Integrating √(32 - x²) from 0 to 4√2 without splitting at x = 4.', 'HARD', true),
        ('12041111-0000-4000-8000-0000000000b9', 'Find the shortest distance between the skew lines:
r = (î + 2ĵ + k̂) + λ(î - ĵ + k̂)
r = (2î - ĵ - k̂) + μ(2î + ĵ + 2k̂).', NULL, NULL, 'LA', 'Mathematics', '3D Geometry', 5, 'Here a₁ = î + 2ĵ + k̂, b₁ = î - ĵ + k̂;
a₂ = 2î - ĵ - k̂, b₂ = 2î + ĵ + 2k̂.
a₂ - a₁ = î - 3ĵ - 2k̂.
b₁ × b₂ = | î ĵ k̂ ; 1 -1 1 ; 2 1 2 | = î(-2 - 1) - ĵ(2 - 2) + k̂(1 + 2) = -3î + 0ĵ + 3k̂.
|b₁ × b₂| = √((-3)² + 0 + 3²) = 3√2.
Dot product: (b₁ × b₂) · (a₂ - a₁) = (-3)(1) + 0(-3) + 3(-2) = -3 - 6 = -9.
Shortest distance d = | -9 | / (3√2) = 3 / √2 = (3√2)/2 units.', 'Compute a₂ - a₁ and b₁ × b₂ [2 Marks] | Magnitude |b₁ × b₂| = 3√2 [1 Mark] | Formula |(b₁×b₂)·(a₂-a₁)| / |b₁×b₂| -> 3/√2 units [2 Marks]', NULL, 'Examiner Tip: If b₁ and b₂ are parallel (b₁ × b₂ = 0), use parallel lines distance |(a₂ - a₁) × b| / |b|! | Common Pitfall: Omitting absolute value around dot product and reporting negative distance.', 'HARD', true),
        ('12041111-0000-4000-8000-0000000000ba', 'Show that the right circular cylinder of given surface area and maximum volume is such that its height is equal to the diameter of its base.', NULL, NULL, 'LA', 'Mathematics', 'Applications of Derivatives', 5, 'Let radius = r, height = h, fixed total surface area S = 2πr² + 2πrh => h = (S - 2πr²) / (2πr).
Volume V = πr² h = πr² [ (S - 2πr²) / (2πr) ] = (Sr)/2 - πr³.
Differentiate w.r.t. r:
dV/dr = S/2 - 3πr² = 0 => S = 6πr².
d²V/dr² = -6πr < 0 => Volume is MAXIMUM.
Substitute S = 6πr² back into S = 2πr² + 2πrh:
6πr² = 2πr² + 2πrh => 4πr² = 2πrh => h = 2r (diameter of base).', 'Express h in terms of S & r -> V(r) = Sr/2 - πr³ [1.5 Marks] | dV/dr = 0 -> S = 6πr² [1.5 Marks] | Second derivative < 0 & deduce h = 2r [2 Marks]', NULL, 'Examiner Tip: Never skip the second-derivative check d²V/dr² < 0 — CBSE awards a full mark for proving maximum! | Common Pitfall: Using CSA = 2πrh instead of Total Surface Area 2πr² + 2πrh.', 'HARD', true),
        ('12041111-0000-4000-8000-0000000000bb', 'Read the case and answer:
In a bolt factory, Machines A, B, and C manufacture respectively 25%, 35%, and 40% of total output. Of their outputs, 5%, 4%, and 2% respectively are defective bolts. A bolt is drawn at random from the product and is found to be defective.

(a) Write the prior probabilities P(A), P(B), P(C) and conditional defect probabilities. (1M)
(b) Find the total probability P(D) that a randomly selected bolt is defective. (1.5M)
(c) Using Bayes'' theorem, find the probability that the defective bolt was manufactured by Machine B. (1.5M)', NULL, NULL, 'CASE', 'Mathematics', 'Case Study', 4, '(a) P(A) = 0.25, P(B) = 0.35, P(C) = 0.40; P(D|A) = 0.05, P(D|B) = 0.04, P(D|C) = 0.02.
(b) P(D) = 0.25(0.05) + 0.35(0.04) + 0.40(0.02) = 0.0125 + 0.0140 + 0.0080 = 0.0345.
(c) P(B|D) = [0.35 × 0.04] / 0.0345 = 0.0140 / 0.0345 = 140 / 345 = 28 / 69.', '(a) Prior & conditional probabilities [1 Mark] | (b) Total probability P(D) = 0.0345 [1.5 Marks] | (c) Bayes formula -> 28/69 [1.5 Marks]', NULL, 'Examiner Tip: Simplify numerator and denominator fractions cleanly (divide by 5 -> 28/69). | Common Pitfall: Leaving out P(A), P(B), P(C) weights in total probability.', 'HARD', true),
        ('12041111-0000-4000-8000-0000000000bc', 'Read the case and answer:
Consider a function f : ℝ - {3} → ℝ - {1} defined by f(x) = (x - 2) / (x - 3).

(a) Show that f is one-one (injective). (1.5M)
(b) Show that f is onto (surjective). (1.5M)
(c) Find the inverse function f⁻¹(y). (1M)', NULL, NULL, 'CASE', 'Mathematics', 'Case Study', 4, '(a) Let f(x₁) = f(x₂) => (x₁ - 2)/(x₁ - 3) = (x₂ - 2)/(x₂ - 3).
Cross-multiplying: x₁x₂ - 3x₁ - 2x₂ + 6 = x₁x₂ - 2x₁ - 3x₂ + 6 => -x₁ = -x₂ => x₁ = x₂. Hence f is one-one.
(b) Let y ∈ ℝ - {1}. Set y = (x - 2)/(x - 3) => xy - 3y = x - 2 => x(y - 1) = 3y - 2 => x = (3y - 2)/(y - 1), which is well-defined and ≠ 3 (since (3y-2)/(y-1) = 3 gives -2 = -3, impossible!). Thus every y has preimage -> onto.
(c) f⁻¹(y) = (3y - 2) / (y - 1).', '(a) Algebraic proof x₁ = x₂ [1.5 Marks] | (b) Express x = (3y-2)/(y-1) and check domain [1.5 Marks] | (c) Inverse expression [1 Mark]', NULL, 'Examiner Tip: Verify x ≠ 3 when proving onto for fractional rational functions! | Common Pitfall: Claiming onto without checking pre-image belongs to domain ℝ - {3}.', 'HARD', true),
        ('12041111-0000-4000-8000-0000000000bd', 'Read the case and answer:
A square piece of tin of side 18 cm is to be made into a box without top by cutting a square of side x cm from each corner and folding up the flaps.

(a) Write the dimensions and Volume V(x) of the open box in terms of x. (1M)
(b) Find the value of x that maximises the volume using derivatives. (2M)
(c) Calculate the maximum possible volume of the box. (1M)', NULL, NULL, 'CASE', 'Mathematics', 'Case Study', 4, '(a) Base side = (18 - 2x) cm, height = x cm (0 < x < 9). Volume V(x) = x(18 - 2x)².
(b) V''(x) = (18 - 2x)² + x · 2(18 - 2x)(-2) = (18 - 2x)(18 - 2x - 4x) = (18 - 2x)(18 - 6x) = 0 => x = 9 (rejected) or x = 3 cm.
V''''(x) at x = 3 is -6(18 - 12) + ... = -72 < 0 => maximum at x = 3 cm.
(c) V_max = 3 × (18 - 6)² = 3 × 144 = 432 cm³.', '(a) V(x) = x(18 - 2x)² [1 Mark] | (b) Derivative check -> x = 3 cm [2 Marks] | (c) V_max = 432 cm³ [1 Mark]', NULL, 'Examiner Tip: Side cut from EACH corner removes 2x from total length 18 cm! | Common Pitfall: Writing base side as (18 - x) instead of (18 - 2x).', 'HARD', true)
